import React, { useMemo, useState, useEffect, useRef } from 'react';
import { Task, User, TaskStatus, Periodicity } from '../types';
import { useI18n } from '../i18n/I18nProvider';
import TaskItem from './TaskItem';
import TaskDetail from './TaskDetail';
import DeleteTaskConfirmation from './DeleteTaskConfirmation';
import { ArrowLeftIcon, ArrowRightIcon } from './Icons';
import {
  formatDayNumber,
  formatDateDDMMYYYY,
  isSameDay,
  startOfWeek,
  endOfWeek,
  addWeeks,
  subWeeks,
  subDays,
  eachDayOfInterval,
  addDays
} from '../utils/date';

interface TaskDashboardProps {
  tasks: Task[];
  users: User[];
  currentUser: User;
  allTasks: Task[]; 
  onEditTask: (task: Task) => void;
  onDeleteTask: (taskId: string, deleteAllFuture?: boolean, selectedDate?: Date) => Promise<void>;
  onCompleteTask: (taskId: string) => Promise<void>;
  onUpdateTaskStatus: (taskId: string, updates: Partial<Task>) => Promise<void>;
  onNewTask: (selectedDate: Date) => void;
  isPremium: boolean;
  onUpdatePeriodicTaskDayAssignment?: (taskId: string, dayIndex: number, assignedTo: string | null, selectedDate?: Date) => Promise<void>;
  onUpdatePeriodicTaskDayStatus?: (taskId: string, dayIndex: number, status: TaskStatus, selectedDate?: Date) => Promise<void>;
  getPeriodicTaskDayInfo?: (task: Task, dayIndex: number) => { status: TaskStatus; assignedTo: string | null };
  onDateChange?: (date: Date) => void;
}

const statusColumns: TaskStatus[] = [ 
  TaskStatus.PENDING, 
  TaskStatus.IN_PROGRESS, 
  TaskStatus.NOT_DONE, 
  TaskStatus.COMPLETED 
];

const DateSelector: React.FC<{
    selectedDate: Date, 
    onDateChange: (date: Date) => void,
    tasks: Task[],
    expandedTasks: Task[],
    users: User[],
    isPremium: boolean,
    onNewTask?: (selectedDate: Date) => void,
}> = ({ selectedDate, onDateChange, tasks, expandedTasks, users, isPremium, onNewTask }) => {
    const { language, t } = useI18n();
    const [weekStart, setWeekStart] = useState(startOfWeek(selectedDate));
    const touchStartXRef = useRef<number | null>(null);
    const touchEndXRef = useRef<number | null>(null);
    const historyLimitDate = useMemo(() => subDays(new Date(), 7), []);

    const weekDays = eachDayOfInterval(weekStart, endOfWeek(weekStart));

    const getIndicatorsForDay = (day: Date) => {
        const tasksForDay = expandedTasks.filter(task => 
            isSameDay(new Date(task.dueDate), day) && task.status !== 'Eliminada'
        );
        if (tasksForDay.length === 0) return null;
        
        const pendingTasks = tasksForDay.filter(task => task.status !== TaskStatus.COMPLETED);
        if (pendingTasks.length === 0) {
            return (
                <div className="flex justify-center -mt-0.5">
                    <span className="inline-flex h-4 w-4 sm:h-5 sm:w-5 items-center justify-center rounded-full bg-emerald-500 shadow-sm ring-1 ring-emerald-300/70">
                        <svg viewBox="0 0 20 20" fill="none" className="h-2.5 w-2.5 sm:h-3 sm:w-3">
                            <path d="M5 10.5l3 3 7-7" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                        </svg>
                    </span>
                </div>
            );
        }

        const allNotDone = pendingTasks.every(task => task.status === TaskStatus.NOT_DONE);
        if (allNotDone) {
            return null;
        }

        const unassignedTasks = pendingTasks.filter(task => !task.assignedTo);
        
        const userColors = [...new Set(pendingTasks
            .map(task => task.assignedTo)
            .filter(Boolean)
            .map(userId => users.find(u => u.id === userId)?.color)
            .filter((color): color is string => !!color)
        )];

        return (
            <div className="flex justify-center items-center gap-1 h-3 sm:h-4 mt-1">
                {userColors.slice(0, 3).map(color => (
                    <span
                        key={color}
                        className="inline-block w-2.5 h-2.5 sm:w-3 sm:h-3 rounded-full border border-white/80 dark:border-slate-800/80 shadow-sm"
                        style={{ backgroundColor: color }}
                    />
                ))}
                {unassignedTasks.length > 0 && (
                    <span className="inline-block w-2.5 h-2.5 sm:w-3 sm:h-3 rounded-full bg-slate-300 dark:bg-slate-500 border border-white/80 dark:border-slate-800/80 shadow-sm" />
                )}
                {pendingTasks.length > 3 && (
                    <span className="text-[9px] sm:text-[10px] font-semibold text-slate-500 dark:text-slate-300">+{pendingTasks.length - 3}</span>
                )}
            </div>
        )
    };

    useEffect(() => {
        // Mantener la semana sincronizada con la fecha seleccionada externa.
        setWeekStart(startOfWeek(selectedDate));
    }, [selectedDate]);

    const onTouchStart = (e: React.TouchEvent<HTMLDivElement>) => {
        touchStartXRef.current = e.changedTouches[0]?.clientX ?? null;
        touchEndXRef.current = null;
    };

    const onTouchEnd = (e: React.TouchEvent<HTMLDivElement>) => {
        touchEndXRef.current = e.changedTouches[0]?.clientX ?? null;
        const startX = touchStartXRef.current;
        const endX = touchEndXRef.current;
        if (startX === null || endX === null) return;

        const deltaX = endX - startX;
        const swipeThreshold = 40;
        if (Math.abs(deltaX) < swipeThreshold) return;

        if (deltaX < 0) {
            setWeekStart(addWeeks(weekStart, 1));
        } else {
            setWeekStart(subWeeks(weekStart, 1));
        }
    };

    return (
        <div
            className="bg-white dark:bg-slate-800/50 p-2 rounded-xl shadow-sm mb-6 flex flex-col items-center touch-pan-y"
            onTouchStart={onTouchStart}
            onTouchEnd={onTouchEnd}
        >
            <div className="flex items-center justify-between w-full mb-2">
                <button onClick={() => setWeekStart(subWeeks(weekStart, 1))} className="p-1 sm:p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700"><ArrowLeftIcon className="w-4 h-4 sm:w-5 sm:h-5"/></button>
                <h3 className="text-xs sm:text-sm font-medium text-slate-600 dark:text-slate-300 text-center">{formatDateDDMMYYYY(weekStart)} - {formatDateDDMMYYYY(endOfWeek(weekStart))}</h3>
                <button onClick={() => setWeekStart(addWeeks(weekStart, 1))} className="p-1 sm:p-2 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700"><ArrowRightIcon className="w-4 h-4 sm:w-5 sm:h-5"/></button>
            </div>
            <div className="grid grid-cols-7 gap-0.5 sm:gap-1 w-full">
                {weekDays.map(day => {
                    const isSelected = isSameDay(day, selectedDate);
                    const isToday = isSameDay(day, new Date());
                    const isDisabled = !isPremium && day < historyLimitDate && !isSameDay(day, historyLimitDate);
                    return (
                        <button 
                            key={day.toString()} 
                            onClick={() => onDateChange(day)}
                            onDoubleClick={() => {
                                if (!isDisabled && onNewTask) {
                                    onNewTask(day);
                                }
                            }}
                            disabled={isDisabled}
                            className={`p-1 sm:p-2 rounded-lg text-center transition-colors ${
                                isSelected 
                                    ? 'bg-primary-600 text-white shadow' 
                                    : isToday 
                                        ? 'bg-blue-200 dark:bg-blue-800 text-blue-800 dark:text-blue-200 hover:bg-blue-300 dark:hover:bg-blue-700' 
                                        : 'hover:bg-slate-100 dark:hover:bg-slate-700'
                            } ${isDisabled ? 'opacity-50 cursor-not-allowed' : ''}`}
                            title={isDisabled ? t('task.date.unavailable') : t('task.date.selectOrCreate')}
                        >
                            <p className="text-xs capitalize">{day.toLocaleDateString(language, { weekday: 'short' })}</p>
                            <p className="font-bold text-base sm:text-lg">{formatDayNumber(day)}</p>
                            <div className="h-3 sm:h-4">{getIndicatorsForDay(day)}</div>
                        </button>
                    )
                })}
            </div>
        </div>
    )
}

const TaskDashboard: React.FC<TaskDashboardProps> = ({
  tasks, users, currentUser, allTasks, onEditTask, onDeleteTask, onCompleteTask, onUpdateTaskStatus, onNewTask, isPremium,
  onUpdatePeriodicTaskDayAssignment, onUpdatePeriodicTaskDayStatus, getPeriodicTaskDayInfo, onDateChange
}) => {
  const { t } = useI18n();
  const [selectedDate, setSelectedDate] = useState(new Date());
  const getStatusLabel = (status: TaskStatus): string => {
    switch (status) {
      case TaskStatus.PENDING:
        return t('task.status.pending');
      case TaskStatus.IN_PROGRESS:
        return t('task.status.inProgress');
      case TaskStatus.NOT_DONE:
        return t('task.status.notDone');
      case TaskStatus.COMPLETED:
        return t('task.status.completed');
      default:
        return String(status);
    }
  };

  const getPeriodicIntervalDays = (task: Task): number => {
    switch (task.periodicity) {
      case Periodicity.WEEKLY:
        return 7;
      case Periodicity.MONTHLY:
        return 30;
      case Periodicity.CUSTOM_DAYS:
        return Math.max(1, task.customDays || 1);
      case Periodicity.DAILY:
      default:
        return 1;
    }
  };

  const normalizeDate = (date: Date): Date => {
    const normalized = new Date(date);
    normalized.setHours(0, 0, 0, 0);
    return normalized;
  };

  const resolvePeriodicOccurrenceDate = (task: Task, dayKey: string, dayInfo: any): Date | null => {
    if (dayInfo?.date) {
      const parsedDate = new Date(dayInfo.date);
      if (!isNaN(parsedDate.getTime())) {
        return parsedDate;
      }
    }

    const startDate = new Date(task.fechaInicio || task.dueDate);
    if (isNaN(startDate.getTime())) {
      return null;
    }

    if (typeof dayInfo?.day === 'number') {
      return addDays(new Date(startDate), dayInfo.day);
    }

    const parsedDayKey = Number.parseInt(dayKey, 10);
    if (!Number.isNaN(parsedDayKey)) {
      const intervalDays = getPeriodicIntervalDays(task);
      return addDays(new Date(startDate), parsedDayKey * intervalDays);
    }

    return null;
  };

  const resolvePeriodicDayKeyByDate = (task: Task, targetDate: Date): number | null => {
    if (task.periodicity === Periodicity.NONE || !task.registroDetallado || Object.keys(task.registroDetallado).length === 0) {
      return null;
    }

    const normalizedTargetDate = normalizeDate(targetDate);

    for (const [dayKey, dayInfo] of Object.entries(task.registroDetallado)) {
      const occurrenceDate = resolvePeriodicOccurrenceDate(task, dayKey, dayInfo);
      if (!occurrenceDate) continue;

      const normalizedOccurrenceDate = normalizeDate(occurrenceDate);
      if (normalizedOccurrenceDate.getTime() === normalizedTargetDate.getTime()) {
        const exactKey = Number.parseInt(dayKey, 10);
        return Number.isNaN(exactKey) ? null : exactKey;
      }
    }

    return null;
  };

  // Función para manejar el cambio de fecha
  const handleDateChange = (date: Date) => {
    setSelectedDate(date);
    if (onDateChange) {
      onDateChange(date);
    }
  };
  const [draggedOverColumn, setDraggedOverColumn] = useState<TaskStatus | null>(null);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isDetailOpen, setIsDetailOpen] = useState(false);
  const [isDeleteConfirmationOpen, setIsDeleteConfirmationOpen] = useState(false);
  const [taskToDelete, setTaskToDelete] = useState<Task | null>(null);
  const [collapsedSections, setCollapsedSections] = useState<Record<TaskStatus, boolean>>({
    [TaskStatus.PENDING]: false,
    [TaskStatus.IN_PROGRESS]: false,
    [TaskStatus.NOT_DONE]: false,
    [TaskStatus.COMPLETED]: false,
    [TaskStatus.DELETED]: false
  });

  // Función para expandir tareas periódicas usando registroDetallado
const expandPeriodicTasks = useMemo(() => {
    const expandedTasks: Task[] = [];
    
    tasks.forEach(task => {
      // Si no es una tarea periódica, la añadimos directamente
      if (task.periodicity === Periodicity.NONE) {
        expandedTasks.push(task);
        return;
      }
      
      // Para tareas periódicas, usar registroDetallado o generar fallback con fechas legacy/nuevas
      const fechaInicio = new Date(task.fechaInicio || task.dueDate);
      const rawFechaFin = task.fechaFin || task.endDate || null;
      const fechaFin = rawFechaFin ? new Date(rawFechaFin) : null;

      if (isNaN(fechaInicio.getTime())) {
        expandedTasks.push(task);
        return;
      }
      
      if (fechaFin && !isNaN(fechaFin.getTime())) {
        // Generar ocurrencias según periodicidad y superponer datos de registroDetallado cuando existan.
        const registryEntries = task.registroDetallado ? Object.entries(task.registroDetallado) : [];
        const intervalDays = getPeriodicIntervalDays(task);
        let occurrenceIndex = 0;
        let dayOffset = 0;

        while (dayOffset >= 0) {
          const currentDate = addDays(new Date(fechaInicio), dayOffset);
          const normalizedCurrentDate = normalizeDate(currentDate);
          const normalizedFechaFin = normalizeDate(fechaFin);
          if (normalizedCurrentDate > normalizedFechaFin) break;

          const matchedByDate = registryEntries.find(([dayKey, dayInfo]) => {
            const occurrenceDate = resolvePeriodicOccurrenceDate(task, dayKey, dayInfo);
            if (!occurrenceDate) return false;
            return normalizeDate(occurrenceDate).getTime() === normalizedCurrentDate.getTime();
          });
          const matchedByKey = task.registroDetallado?.[occurrenceIndex.toString()];
          const dayInfo = (matchedByDate ? matchedByDate[1] : matchedByKey) || null;

          const expandedTask: Task = {
            ...task,
            dueDate: currentDate.toISOString(),
            status: (dayInfo?.status as TaskStatus) || task.status || TaskStatus.PENDING,
            assignedTo: dayInfo?.assignedTo || task.assignedTo || null,
            registro: undefined
          };

          expandedTasks.push(expandedTask);
          occurrenceIndex += 1;
          dayOffset = occurrenceIndex * intervalDays;
        }
      } else if (task.registroDetallado && Object.keys(task.registroDetallado).length > 0) {
        // Si no hay fecha fin, usar lo que exista en registroDetallado.
        Object.keys(task.registroDetallado).forEach(dayKey => {
          const dayInfo = task.registroDetallado![dayKey];
          const currentDate = resolvePeriodicOccurrenceDate(task, dayKey, dayInfo);
          if (!currentDate || isNaN(currentDate.getTime())) return;

          expandedTasks.push({
            ...task,
            dueDate: currentDate.toISOString(),
            status: (dayInfo.status as TaskStatus) || TaskStatus.PENDING,
            assignedTo: dayInfo.assignedTo || null,
            registro: undefined
          });
        });
      } else {
        expandedTasks.push(task);
      }
    });
    
    return expandedTasks;
  }, [tasks]);

const tasksForSelectedDate = useMemo(() => {
    return expandPeriodicTasks.filter(task => 
      isSameDay(new Date(task.dueDate), selectedDate) && task.status !== 'Eliminada'
    );
  }, [expandPeriodicTasks, selectedDate]);

  const tasksByStatus = useMemo(() => {
    return statusColumns.reduce((acc, status) => {
      acc[status] = tasksForSelectedDate
        .filter(task => task.status === status)
        .sort((a,b) => new Date(a.createdAt as string).getTime() - new Date(b.createdAt as string).getTime());
      return acc;
    }, {} as Record<TaskStatus, Task[]>);
  }, [tasksForSelectedDate]);

  const handleDragStart = (e: React.DragEvent<HTMLDivElement>, task: Task) => {
    const dragPayload = JSON.stringify({
      taskId: task.id,
      dueDate: task.dueDate,
    });
    e.dataTransfer.setData('taskPayload', dragPayload);
    e.dataTransfer.setData('taskId', task.id); // compatibilidad
  };
  const handleDragOver = (e: React.DragEvent<HTMLDivElement>, status: TaskStatus) => { e.preventDefault(); setDraggedOverColumn(status); };
  const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => { e.preventDefault(); setDraggedOverColumn(null); };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>, newStatus: TaskStatus) => {
    e.preventDefault();
    setDraggedOverColumn(null);
    const rawPayload = e.dataTransfer.getData('taskPayload');
    const fallbackTaskId = e.dataTransfer.getData('taskId');

    let taskId = fallbackTaskId;
    let taskDueDate: string | null = null;
    try {
      if (rawPayload) {
        const parsed = JSON.parse(rawPayload);
        taskId = parsed?.taskId || fallbackTaskId;
        taskDueDate = parsed?.dueDate || null;
      }
    } catch {
      // ignore malformed payload and fallback by taskId
    }

    const task = expandPeriodicTasks.find(t => {
      if (t.id !== taskId) return false;
      if (!taskDueDate) return true;
      return new Date(t.dueDate).toISOString() === new Date(taskDueDate).toISOString();
    });
    
    console.log('🔄 handleDrop called:', { taskId, newStatus, task: task?.title, currentStatus: task?.status });
    
    if (task && task.status !== newStatus) {
      // Calcular dayIndex para tareas periódicas
      const getDayIndex = () => {
        if (task.periodicity === Periodicity.NONE || !task.fechaInicio) {
          return null;
        }
        
        if (task.registroDetallado && Object.keys(task.registroDetallado).length > 0) {
          const resolvedDayKey = resolvePeriodicDayKeyByDate(task, new Date(task.dueDate));
          if (resolvedDayKey !== null) {
            return resolvedDayKey;
          }
        }
        
        // Fallback: calcular como diferencia de días
        const taskDate = new Date(task.dueDate);
        const startDate = new Date(task.fechaInicio);
        taskDate.setHours(0, 0, 0, 0);
        startDate.setHours(0, 0, 0, 0);
        
        const diffTime = taskDate.getTime() - startDate.getTime();
        return Math.floor(diffTime / (1000 * 60 * 60 * 24));
      };
      
      const dayIndex = getDayIndex();
      const isPeriodicTask = task.periodicity !== Periodicity.NONE && dayIndex !== null;
      
      console.log('🔍 Task analysis:', { isPeriodicTask, dayIndex, periodicity: task.periodicity });
      
      if (isPeriodicTask && onUpdatePeriodicTaskDayStatus) {
        // Para tareas periódicas, usar siempre onUpdatePeriodicTaskDayStatus
        console.log('📅 Calling onUpdatePeriodicTaskDayStatus:', { taskId, dayIndex, newStatus, selectedDate });
        onUpdatePeriodicTaskDayStatus(taskId, dayIndex!, newStatus, selectedDate);
      } else {
        // Para tareas normales
        console.log('📝 Calling normal task update:', { taskId, newStatus });
        if (newStatus === TaskStatus.COMPLETED) {
          onCompleteTask(taskId);
        } else {
          if (task.status === TaskStatus.COMPLETED) {
            onUpdateTaskStatus(taskId, { status: newStatus, completedBy: undefined, completedAt: undefined });
          } else {
            onUpdateTaskStatus(taskId, { status: newStatus });
          }
        }
      }
      // No abrir los detalles de la tarea cuando cambia de fase
      // setSelectedTask(task);
      // setIsDetailOpen(true);
    }
  };

  const getStatusColor = (status: TaskStatus) => {
    switch (status) {
        case TaskStatus.PENDING: return 'bg-yellow-100 dark:bg-yellow-900/50 text-yellow-800 dark:text-yellow-300';
        case TaskStatus.IN_PROGRESS: return 'bg-blue-100 dark:bg-blue-900/50 text-blue-800 dark:text-blue-300';
        case TaskStatus.NOT_DONE: return 'bg-gray-100 dark:bg-gray-700/50 text-gray-800 dark:text-gray-300';
        case TaskStatus.COMPLETED: return 'bg-green-100 dark:bg-green-900/50 text-green-800 dark:text-green-300';
    }
  }

  const toggleSection = (status: TaskStatus) => {
    setCollapsedSections(prev => ({
      ...prev,
      [status]: !prev[status]
    }));
  };

  const handleTaskClick = (task: Task) => {
    setSelectedTask(task);
    setIsDetailOpen(true);
  };

  const handleDeleteClick = (task: Task) => {
    console.log('[TaskDashboard] handleDeleteClick:', {
      taskId: task.id,
      taskTitle: task.title,
      taskDueDate: task.dueDate,
      taskPeriodicity: task.periodicity,
      selectedDate: selectedDate?.toISOString()
    });
    setTaskToDelete(task);
    setIsDeleteConfirmationOpen(true);
  };

  const handleConfirmDelete = (deleteAll: boolean) => {
    if (taskToDelete) {
      console.log('[TaskDashboard] handleConfirmDelete:', {
        taskId: taskToDelete.id,
        deleteAll,
        selectedDate: selectedDate?.toISOString()
      });
      
      // Usar siempre la fecha del selector superior
      onDeleteTask(taskToDelete.id, deleteAll, selectedDate);

      setIsDeleteConfirmationOpen(false);
      setTaskToDelete(null);
    }
  };

  return (
    <div className="min-h-screen w-full px-2 sm:px-4">
      <DateSelector 
        selectedDate={selectedDate} 
        onDateChange={handleDateChange} 
        tasks={allTasks}
        expandedTasks={expandPeriodicTasks}
        users={users} 
        isPremium={isPremium}
        onNewTask={onNewTask}
      />

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6 w-full">
        {statusColumns.map(status => (
          <div 
            key={status} 
            onDragOver={(e) => handleDragOver(e, status)} 
            onDragLeave={handleDragLeave} 
            onDrop={(e) => handleDrop(e, status)}
            className={`bg-slate-100/50 dark:bg-slate-800/50 rounded-xl p-4 flex flex-col transition-all duration-300 
              ${draggedOverColumn === status ? 'ring-2 ring-primary-500 bg-primary-50 dark:bg-primary-900/20' : ''}`}
          >
            <div 
              className="flex items-center justify-between mb-4 cursor-pointer"
              onClick={() => toggleSection(status)}
            >
              <div className={`text-sm font-bold px-3 py-1 rounded-full self-start ${getStatusColor(status)}`}>
                {getStatusLabel(status)} ({tasksByStatus[status].length})
              </div>
              <button className="text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200">
                {collapsedSections[status] ? (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                  </svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" />
                  </svg>
                )}
              </button>
            </div>

            {/* Lista sin límites ni scroll interno */}
            <div className={`space-y-4 transition-all duration-300 ${collapsedSections[status] ? 'hidden' : 'opacity-100'}`}>
              {tasksByStatus[status].length > 0 ? (
                tasksByStatus[status].map(task => (
                  <TaskItem 
                    key={`${task.id}-${task.dueDate}`} 
                    task={task} 
                    users={users} 
                    onEdit={() => onEditTask(task)} 
                    onDelete={() => handleDeleteClick(task)} 
                    onComplete={() => onCompleteTask(task.id)}
                    onUpdateStatus={(newStatus) => onUpdateTaskStatus(task.id, { status: newStatus })} 
                    onDragStart={(e) => handleDragStart(e, task)} 
                    onTaskClick={handleTaskClick}
                    onUpdatePeriodicTaskDayStatus={onUpdatePeriodicTaskDayStatus}
                    getPeriodicTaskDayInfo={getPeriodicTaskDayInfo}
                  />
                ))
              ) : (
                <div className="text-center pt-4 text-slate-500 dark:text-slate-400 text-sm">
                  <p>{t('task.empty.byStatus')}</p>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      <TaskDetail 
        task={selectedTask} 
        users={users} 
        isOpen={isDetailOpen} 
        onClose={() => setIsDetailOpen(false)}
        onUpdatePeriodicTaskDayAssignment={onUpdatePeriodicTaskDayAssignment}
        onUpdatePeriodicTaskDayStatus={onUpdatePeriodicTaskDayStatus}
        getPeriodicTaskDayInfo={getPeriodicTaskDayInfo}
      />

      <DeleteTaskConfirmation
        isOpen={isDeleteConfirmationOpen}
        onClose={() => setIsDeleteConfirmationOpen(false)}
        onConfirmDelete={handleConfirmDelete}
        isPeriodic={taskToDelete?.periodicity !== Periodicity.NONE}
      />
    </div>
  );
};

export default TaskDashboard;
