  // Verificar si debe mostrar promoción premium (mejorado con analytics)
  async shouldShowPremiumPromotion(user: User): Promise<boolean> {
    if (user.plan === 'premium') return false;
    
    const settings = await this.getNotificationSettings(user.id);
    if (!settings || !settings.premiumPromotionEnabled) return false;

    // No mostrar si se mostró en los últimos 2 meses
    if (settings.lastPremiumPromotionShown) {
      const twoMonthsAgo = new Date();
      twoMonthsAgo.setMonth(twoMonthsAgo.getMonth() - 2);
      
      if (settings.lastPremiumPromotionShown.toDate() > twoMonthsAgo) {
        return false;
      }
    }

    // Verificar triggers inteligentes basados en comportamiento
    const intelligentTriggers = await this.analyticsService.detectIntelligentPromotionTriggers(user.id);
    if (intelligentTriggers.length > 0) {
      console.log('Intelligent promotion triggers detected:', intelligentTriggers);
      return true;
    }

    // Lógica original como fallback
    const shouldShow = settings.loginCount >= 10 || 
                      (settings.loginCount >= 5 && Math.random() < 0.3);
    
    return shouldShow;
  }

  // Crear configuraciones por defecto para nuevo usuario
  async createDefaultNotificationSettings(userId: string): Promise<void> {
    const defaultSettings: NotificationSettings = {
      userId,
      taskReminderTime: '09:00',
      taskReminderEnabled: true,
      pushNotificationsEnabled: true,
      emailNotificationsEnabled: true,
      premiumPromotionEnabled: true,
      loginCount: 0,
      createdAt: Timestamp.now(),
      updatedAt: Timestamp.now()
    };

    await this.updateNotificationSettings(defaultSettings);
  }

