import React, { useState, useMemo } from 'react';
import { Task, User, TaskStatus, Periodicity, DailyTaskRecord } from '../types';

const addDays = (date: Date, days: number): Date => {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
};

interface PeriodicTaskDayManagerProps {
  task: Task;
  users: User[];
  onUpdateDayAssignment: (dayIndex: number, assignedTo: string | null, specificDate: Date) => Promise<void>;
  onUpdateDayStatus: (dayIndex: number, status: TaskStatus, specificDate: Date) => Promise<void>;
  getPeriodicTaskDayInfo?: (task: Task, dayIndex: number) => { status: TaskStatus; assignedTo: string | null };
}

const PeriodicTaskDayManager: React.FC<PeriodicTaskDayManagerProps> = ({
  task,
  users,
  onUpdateDayAssignment,
  onUpdateDayStatus,
  getPeriodicTaskDayInfo
}) => {
  const getPeriodicIntervalDays = (): number => {
    switch (task.periodicity) {
      case Periodicity.WEEKLY:
        return 7;
      case Periodicity.MONTHLY:
        return 30;
      case Periodicity.CUSTOM_DAYS:
        return Math.max(1, task.customDays || 1);
      case Periodicity.DAILY:
      default:
        return 1;
    }
  };

  const resolveOccurrenceDate = (dayKey: string, dayRecord: DailyTaskRecord): Date => {
    if (dayRecord?.date) {
      const parsed = new Date(dayRecord.date);
      if (!isNaN(parsed.getTime())) {
        return parsed;
      }
    }

    const startDate = new Date(task.fechaInicio || task.dueDate);
    const dayOffset =
      typeof dayRecord?.day === 'number'
        ? dayRecord.day
        : Number.parseInt(dayKey, 10) * getPeriodicIntervalDays();
    return addDays(startDate, Number.isNaN(dayOffset) ? 0 : dayOffset);
  };

  // Estado local para los valores de los selects
  const [localStatuses, setLocalStatuses] = useState<{[key: number]: TaskStatus}>({});
  const [localAssignments, setLocalAssignments] = useState<{[key: number]: string | null}>({});
  const [expandedDay, setExpandedDay] = useState<number | null>(null);

  // Calcular los días de la tarea periódica
  const taskDays = useMemo(() => {
    if (task.periodicity === Periodicity.NONE) {
      return [];
    }

    const days = [];
    
    // Si tenemos registroDetallado, usar las fechas específicas almacenadas
    if (task.registroDetallado && getPeriodicTaskDayInfo) {
      Object.entries(task.registroDetallado).forEach(([dayKey, dayRecord]) => {
        const dayIndex = parseInt(dayKey);
        const dayInfo = getPeriodicTaskDayInfo(task, dayIndex);
        
        days.push({
          index: dayIndex,
          date: resolveOccurrenceDate(dayKey, dayRecord),
          status: dayInfo.status,
          assignedTo: dayInfo.assignedTo
        });
      });
    } else if (task.fechaInicio && task.fechaFin && getPeriodicTaskDayInfo) {
      // Fallback al método anterior si no hay registroDetallado
      const startDate = new Date(task.fechaInicio);
      const endDate = new Date(task.fechaFin);
      const intervalDays = getPeriodicIntervalDays();
      let occurrenceIndex = 0;

      for (let dayOffset = 0; dayOffset >= 0; dayOffset += intervalDays) {
        const currentDate = addDays(new Date(startDate), dayOffset);
        if (currentDate > endDate) break;
        
        const dayInfo = getPeriodicTaskDayInfo(task, occurrenceIndex);
        
        days.push({
          index: occurrenceIndex,
          date: currentDate,
          status: dayInfo.status,
          assignedTo: dayInfo.assignedTo
        });
        occurrenceIndex += 1;
      }
    }
    
    // Ordenar por índice del día
    return days.sort((a, b) => a.index - b.index);
  }, [task, getPeriodicTaskDayInfo]);

  const taskDayDateMap = useMemo(() => {
    return taskDays.reduce((acc, day) => {
      acc[day.index] = day.date;
      return acc;
    }, {} as Record<number, Date>);
  }, [taskDays]);

  const formatDate = (date: Date) => {
    return date.toLocaleDateString('es-ES', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    });
  };

  const getStatusColor = (status: TaskStatus) => {
    switch (status) {
      case TaskStatus.COMPLETED:
        return 'bg-green-100 dark:bg-green-900/30 text-green-800 dark:text-green-300';
      case TaskStatus.IN_PROGRESS:
        return 'bg-blue-100 dark:bg-blue-900/30 text-blue-800 dark:text-blue-300';
      case TaskStatus.NOT_DONE:
        return 'bg-gray-100 dark:bg-gray-700/30 text-gray-800 dark:text-gray-300';
      default:
        return 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-300';
    }
  };

  const handleStatusChange = async (dayIndex: number, newStatus: TaskStatus) => {
    // Actualizar inmediatamente el estado local
    setLocalStatuses(prev => ({ ...prev, [dayIndex]: newStatus }));
    
    try {
      const specificDate = taskDayDateMap[dayIndex]
        ? new Date(taskDayDateMap[dayIndex])
        : addDays(new Date(task.fechaInicio || task.dueDate), dayIndex);
      await onUpdateDayStatus(dayIndex, newStatus, specificDate);
    } catch (error) {
      console.error('Error al actualizar estado del día:', error);
      // En caso de error, revertir el estado local
      setLocalStatuses(prev => {
        const newState = { ...prev };
        delete newState[dayIndex];
        return newState;
      });
    }
  };

  const handleAssignmentChange = async (dayIndex: number, userId: string | null) => {
    // Actualizar inmediatamente el estado local
    setLocalAssignments(prev => ({ ...prev, [dayIndex]: userId }));
    
    try {
      const specificDate = taskDayDateMap[dayIndex]
        ? new Date(taskDayDateMap[dayIndex])
        : addDays(new Date(task.fechaInicio || task.dueDate), dayIndex);
      await onUpdateDayAssignment(dayIndex, userId, specificDate);
    } catch (error) {
      console.error('Error al actualizar asignación del día:', error);
      // En caso de error, revertir el estado local
      setLocalAssignments(prev => {
        const newState = { ...prev };
        delete newState[dayIndex];
        return newState;
      });
    }
  };

  if (task.periodicity === Periodicity.NONE) {
    return null;
  }

  return (
    <div className="mt-6">
      <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-4">
        Gestión Diaria de Tarea Periódica
      </h3>
      
      <div className="space-y-2 max-h-64 overflow-y-auto">
          {taskDays.map((day) => {
            const dayInfo = getPeriodicTaskDayInfo ? getPeriodicTaskDayInfo(task, day.index) : { status: day.status, assignedTo: day.assignedTo };
            
            // Usar estado local si existe, sino usar el valor del backend
            const currentStatus = localStatuses[day.index] !== undefined ? localStatuses[day.index] : dayInfo.status;
            const currentAssignment = localAssignments[day.index] !== undefined ? localAssignments[day.index] : dayInfo.assignedTo;
            
            const assignedUser = currentAssignment ? users.find(u => u.id === currentAssignment) : null;
          const isExpanded = expandedDay === day.index;
          
          return (
            <div key={day.index} className="border border-slate-200 dark:border-slate-700 rounded-lg">
              <div 
                className="p-3 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors"
                onClick={() => setExpandedDay(isExpanded ? null : day.index)}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <span className="text-sm font-medium text-slate-600 dark:text-slate-400">
                      Día {day.index + 1}
                    </span>
                    <span className="text-sm text-slate-500 dark:text-slate-400">
                      {formatDate(day.date)}
                    </span>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    <span className={`text-xs px-2 py-1 rounded-full font-medium ${getStatusColor(currentStatus)}`}>
                      {currentStatus}
                    </span>
                    
                    {assignedUser && (
                      <span className="text-xs text-slate-600 dark:text-slate-400">
                        {assignedUser.name}
                      </span>
                    )}
                    
                    <span className="text-slate-400 dark:text-slate-500">
                      {isExpanded ? '▼' : '▶'}
                    </span>
                  </div>
                </div>
              </div>
              
              {isExpanded && (
                <div className="px-3 pb-3 border-t border-slate-200 dark:border-slate-700">
                  <div className="pt-3 space-y-3">
                    {/* Selector de estado */}
                    <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                        Estado:
                      </label>
                      <select
                        value={currentStatus}
                        onChange={(e) => handleStatusChange(day.index, e.target.value as TaskStatus)}
                        className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-md bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 text-sm"
                      >
                        <option value={TaskStatus.PENDING}>Pendiente</option>
                        <option value={TaskStatus.IN_PROGRESS}>En proceso</option>
                        <option value={TaskStatus.COMPLETED}>Completada</option>
                        <option value={TaskStatus.NOT_DONE}>No realizada</option>
                      </select>
                    </div>
                    
                    {/* Selector de asignación */}
                    <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                        Asignado a:
                      </label>
                      <select
                        value={currentAssignment || ''}
                        onChange={(e) => handleAssignmentChange(day.index, e.target.value || null)}
                        className="w-full p-2 border border-slate-300 dark:border-slate-600 rounded-md bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 text-sm"
                      >
                        <option value="">Sin asignar</option>
                        {users.map(user => (
                          <option key={user.id} value={user.id}>
                            {user.name}
                          </option>
                        ))}
                      </select>
                    </div>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default PeriodicTaskDayManager;
