import { GoogleAuthProvider, OAuthProvider, signInWithPopup, signInWithRedirect, signInWithCredential } from 'firebase/auth';
import { auth } from './firebase';
import { User } from '../types';

// Proveedor de autenticación de Google
export const googleProvider = new GoogleAuthProvider();
export const appleProvider = new OAuthProvider('apple.com');
appleProvider.addScope('email');
appleProvider.addScope('name');

interface NativeAppleSignInPlugin {
  signIn(options: { nonce?: string; state?: string }): Promise<{
    identityToken: string;
    authorizationCode?: string;
    user?: string;
    email?: string;
    givenName?: string;
    familyName?: string;
  }>;
}

const getCapacitorRuntime = (): any => {
  if (typeof window === 'undefined') return null;
  return (window as any).Capacitor || null;
};

const mapAuthUserToAppUser = (user: any, fallbackColor: string = '#3b82f6'): User => ({
  id: user.uid,
  name: user.displayName || 'Usuario',
  email: user.email || '',
  avatar: user.photoURL || `https://i.pravatar.cc/150?u=${user.email || user.uid}`,
  color: fallbackColor,
  plan: 'free',
});

const generateNonce = (length: number = 32): string => {
  const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-._';
  let result = '';
  const randomValues = new Uint8Array(length);

  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    crypto.getRandomValues(randomValues);
  } else {
    for (let i = 0; i < length; i++) {
      randomValues[i] = Math.floor(Math.random() * 256);
    }
  }

  for (let i = 0; i < length; i++) {
    result += chars[randomValues[i] % chars.length];
  }

  return result;
};

/**
 * Inicia sesión con Google usando un popup
 * @returns Promise con el resultado de la autenticación
 */
export const signInWithGoogle = async (): Promise<{ success: boolean; message: string; user?: User }> => {
  try {
    const result = await signInWithPopup(auth, googleProvider);
    const user = result.user;
    
    // Crear objeto de usuario con la información de Google
    const userData: User = mapAuthUserToAppUser(user, '#3b82f6');
    
    return { 
      success: true, 
      message: '¡Inicio de sesión con Google exitoso!',
      user: userData
    };
  } catch (error: any) {
    console.error('Error al iniciar sesión con Google:', error);
    
    // Mejorar los mensajes de error para hacerlos más amigables
    let errorMessage = 'Error al iniciar sesión con Google';
    
    if (error.code) {
      switch (error.code) {
        case 'auth/popup-closed-by-user':
          errorMessage = 'Has cerrado la ventana de inicio de sesión. Por favor, inténtalo de nuevo.';
          break;
        case 'auth/popup-blocked':
          errorMessage = 'El navegador ha bloqueado la ventana emergente. Por favor, permite ventanas emergentes e inténtalo de nuevo.';
          break;
        case 'auth/cancelled-popup-request':
          errorMessage = 'La solicitud de inicio de sesión fue cancelada. Por favor, inténtalo de nuevo.';
          break;
        case 'auth/account-exists-with-different-credential':
          errorMessage = 'Ya existe una cuenta con este correo electrónico pero con otro método de inicio de sesión.';
          break;
        case 'auth/network-request-failed':
          errorMessage = 'Error de conexión. Por favor, verifica tu conexión a internet e inténtalo de nuevo.';
          break;
        default:
          errorMessage = 'No se pudo iniciar sesión con Google. Por favor, inténtalo de nuevo más tarde.';
      }
    }
    
    return { 
      success: false, 
      message: errorMessage
    };
  }
};

/**
 * Inicia sesión con Apple usando Firebase Authentication.
 * En entornos donde popup no está soportado, intenta redirect.
 */
export const signInWithApple = async (): Promise<{ success: boolean; message: string; user?: User }> => {
  try {
    const capacitorRuntime = getCapacitorRuntime();
    const isNative = !!capacitorRuntime?.isNativePlatform?.();
    const platform = capacitorRuntime?.getPlatform?.() || 'web';
    const applePlugin = capacitorRuntime?.Plugins?.AppleSignIn as NativeAppleSignInPlugin | undefined;

    if (isNative && platform === 'ios' && applePlugin?.signIn) {
      const rawNonce = generateNonce();
      const nativeResult = await applePlugin.signIn({ nonce: rawNonce });

      if (!nativeResult?.identityToken) {
        return { success: false, message: 'Apple no devolvió un token válido.' };
      }

      const credential = appleProvider.credential({
        idToken: nativeResult.identityToken,
        rawNonce,
      });

      const firebaseResult = await signInWithCredential(auth, credential);
      const userData = mapAuthUserToAppUser(firebaseResult.user, '#111827');

      if (!userData.name || userData.name === 'Usuario') {
        const fullName = `${nativeResult.givenName || ''} ${nativeResult.familyName || ''}`.trim();
        if (fullName) {
          userData.name = fullName;
        }
      }

      if (!userData.email && nativeResult.email) {
        userData.email = nativeResult.email;
      }

      return {
        success: true,
        message: '¡Inicio de sesión con Apple exitoso!',
        user: userData,
      };
    }

    const result = await signInWithPopup(auth, appleProvider);
    const userData: User = mapAuthUserToAppUser(result.user, '#111827');

    return {
      success: true,
      message: '¡Inicio de sesión con Apple exitoso!',
      user: userData,
    };
  } catch (error: any) {
    console.error('Error al iniciar sesión con Apple:', error);

    // Fallback para entornos móviles/WebView donde popup no funciona bien.
    if (
      error?.code === 'auth/popup-blocked' ||
      error?.code === 'auth/operation-not-supported-in-this-environment' ||
      error?.code === 'auth/cancelled-popup-request'
    ) {
      try {
        await signInWithRedirect(auth, appleProvider);
        return { success: true, message: 'Redirigiendo a Apple...' };
      } catch (redirectError: any) {
        console.error('Error en redirect con Apple:', redirectError);
      }
    }

    let errorMessage = 'No se pudo iniciar sesión con Apple.';

    if (error?.code) {
      switch (error.code) {
        case 'auth/account-exists-with-different-credential':
          errorMessage = 'Ya existe una cuenta con este correo usando otro método de inicio de sesión.';
          break;
        case 'auth/popup-closed-by-user':
          errorMessage = 'Has cerrado la ventana de Apple. Inténtalo de nuevo.';
          break;
        case 'auth/unauthorized-domain':
          errorMessage = 'Dominio no autorizado en Firebase para Apple Sign-In.';
          break;
        case 'auth/network-request-failed':
          errorMessage = 'Error de conexión. Verifica tu internet e inténtalo de nuevo.';
          break;
        default:
          errorMessage = 'Error al iniciar sesión con Apple. Inténtalo más tarde.';
      }
    }

    return {
      success: false,
      message: errorMessage,
    };
  }
};
