export const isSameDay = (a: Date, b: Date) => 
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

export const formatShortDay = (date: Date) =>
  date.toLocaleDateString('es-ES', { weekday: 'short' }); // ej: "lun"

export const formatDayNumber = (date: Date) => date.getDate().toString();

export const formatFullDate = (date: Date) =>
  date.toLocaleDateString('es-ES', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  });

export const formatDateDDMMYYYY = (date: Date) =>
  date.toLocaleDateString('es-ES', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });

export const startOfWeek = (date: Date) => {
  const day = date.getDay();
  const diff = (day === 0 ? -6 : 1) - day;
  const start = new Date(date);
  start.setDate(date.getDate() + diff);
  start.setHours(0, 0, 0, 0);
  return start;
};

export const endOfWeek = (date: Date) => {
  const start = startOfWeek(date);
  const end = new Date(start);
  end.setDate(start.getDate() + 6);
  end.setHours(23, 59, 59, 999);
  return end;
};

export const addWeeks = (date: Date, count: number) => {
  const result = new Date(date);
  result.setDate(result.getDate() + count * 7);
  return result;
};

export const subWeeks = (date: Date, count: number) => addWeeks(date, -count);

export const subDays = (date: Date, days: number) => {
  const result = new Date(date);
  result.setDate(result.getDate() - days);
  return result;
};

export const eachDayOfInterval = (start: Date, end: Date) => {
  const days = [];
  const current = new Date(start);
  while (current <= end) {
    days.push(new Date(current));
    current.setDate(current.getDate() + 1);
  }
  return days;
};

export const isThisWeek = (date: Date) => {
  const today = new Date();
  const startDate = new Date(today);
  
  // Ajustar al lunes más reciente
  const dayOfWeek = (today.getDay() + 6) % 7;
  startDate.setDate(today.getDate() - dayOfWeek);
  startDate.setHours(0, 0, 0, 0);

  const endDate = new Date(startDate);
  endDate.setDate(startDate.getDate() + 6);
  endDate.setHours(23, 59, 59, 999);

  return date >= startDate && date <= endDate;
};

export const isThisMonth = (date: Date) => {
  const today = new Date();
  return date.getMonth() === today.getMonth() && date.getFullYear() === today.getFullYear();
};

export const isThisYear = (date: Date) => {
  const today = new Date();
  return date.getFullYear() === today.getFullYear();
};

export const addDays = (date: Date, days: number) => {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
};
