import React, { useState, useMemo } from 'react';
import { User, Stats, Home } from '../types';
import { useI18n } from '../i18n/I18nProvider';

interface StatsPageProps {
  users: User[];
  getStats: (userId: string, period: 'weekly' | 'monthly' | 'annually') => Stats;
  currentHome: Home | undefined;
  isPremium: boolean;
}

const LockIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4 inline-block ml-1">
        <path fillRule="evenodd" d="M10 1a4.5 4.5 0 00-4.5 4.5V9H5a2 2 0 00-2 2v6a2 2 0 002 2h10a2 2 0 002-2v-6a2 2 0 00-2-2h-.5V5.5A4.5 4.5 0 0010 1zm3 8V5.5a3 3 0 10-6 0V9h6z" clipRule="evenodd" />
    </svg>
);

const TrophyIcon = ({ colorClass }: { colorClass: string}) => (
  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className={`w-8 h-8 ${colorClass}`}>
    <path fillRule="evenodd" d="M11.624 2.12a.75.75 0 0 1 .752 0l2.036.958a.75.75 0 0 0 .684.053l2.434-.926a.75.75 0 0 1 .91.688l-.29 2.504a.75.75 0 0 0 .423.73l2.28.912a.75.75 0 0 1 .374.998l-1.462 2.193a.75.75 0 0 0 .097.835l1.83 1.83a.75.75 0 0 1-.53 1.28l-2.432-.54a.75.75 0 0 0-.74.19l-1.63 1.956a.75.75 0 0 1-1.012 0l-1.63-1.956a.75.75 0 0 0-.74-.19l-2.432.54a.75.75 0 0 1-.53-1.28l1.83-1.83a.75.75 0 0 0 .097-.835L2.53 11.002a.75.75 0 0 1 .374-.998l2.28-.912a.75.75 0 0 0 .423-.73l-.29-2.504a.75.75 0 0 1 .91-.688l2.434.926a.75.75 0 0 0 .684-.053l2.036-.958ZM12 6.375a5.625 5.625 0 1 0 0 11.25 5.625 5.625 0 0 0 0-11.25Z" clipRule="evenodd" />
    <path d="M12.75 18.165a.75.75 0 0 0-1.5 0V21a.75.75 0 0 0 1.5 0v-2.835Z" />
    <path d="M8.25 21a.75.75 0 0 1 .75-.75h6a.75.75 0 0 1 0 1.5H9a.75.75 0 0 1-.75-.75Z" />
  </svg>
);

const StatsPage: React.FC<StatsPageProps> = ({ users, getStats, currentHome, isPremium }) => {
  const { t } = useI18n();
  const [period, setPeriod] = useState<'weekly' | 'monthly' | 'annually'>('weekly');

  const userStats = useMemo(() => {
    if (!currentHome) return [];
    
    // Obtener todos los usuarios que han completado tareas en esta casa
    const userIdsWithStats = new Set<string>();
    
    // Primero añadimos los miembros actuales
    currentHome.memberIds.forEach(id => userIdsWithStats.add(id));
    
    // Luego buscamos usuarios que han completado tareas pero ya no son miembros
    // Esto se hace indirectamente a través de getStats que ya tiene esta información
    users.forEach(user => {
      const stats = getStats(user.id, period);
      if (stats.tasksCompleted > 0 || stats.pointsEarned > 0) {
        userIdsWithStats.add(user.id);
      }
    });
    
    return Array.from(userIdsWithStats)
      .map(userId => {
        const user = users.find(u => u.id === userId);
        const isCurrentMember = currentHome.memberIds.includes(userId);
        
        return {
          id: userId,
          name: user?.name || t('stats.user.defaultName'),
          avatar: user?.avatar || '/user.svg',
          color: user?.color || '#cccccc',
          isCurrentMember,
          stats: getStats(userId, period),
        };
      })
      .filter(user => user.stats.tasksCompleted > 0 || user.stats.pointsEarned > 0) // Solo mostrar usuarios con actividad
      .sort((a, b) => {
        const pointsA = a.stats.pointsEarned;
        const pointsB = b.stats.pointsEarned;
        if (pointsB !== pointsA) return pointsB - pointsA;
        return b.stats.tasksCompleted - a.stats.tasksCompleted;
      });
  }, [users, getStats, period, currentHome]);

  const rankingColors = ['text-yellow-400', 'text-slate-400', 'text-yellow-600'];
  const premiumPeriods: ('monthly' | 'annually')[] = ['monthly', 'annually'];

  return (
    <div className="space-y-8">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <h2 className="text-3xl font-bold text-slate-900 dark:text-white">
          {t('stats.title', { homeName: currentHome?.name || '' })}
        </h2>
        <div className="bg-slate-200 dark:bg-slate-700 p-1 rounded-lg flex space-x-1">
          <button onClick={() => setPeriod('weekly')} className={`px-4 py-1.5 text-sm font-semibold rounded-md transition-all ${period === 'weekly' ? 'bg-white dark:bg-slate-800 shadow-sm text-primary-600 dark:text-primary-400' : 'text-slate-600 dark:text-slate-300'}`}>
            {t('stats.period.week')}
          </button>
           {premiumPeriods.map(p => (
            <div key={p} className="relative group">
                <button
                    onClick={() => isPremium && setPeriod(p)}
                    disabled={!isPremium}
                    className={`px-4 py-1.5 text-sm font-semibold rounded-md transition-all capitalize ${period === p ? 'bg-white dark:bg-slate-800 shadow-sm text-primary-600 dark:text-primary-400' : 'text-slate-600 dark:text-slate-300'} ${!isPremium ? 'cursor-not-allowed opacity-60' : ''}`}
                >
                    {p === 'monthly' ? t('stats.period.month') : t('stats.period.year')} {!isPremium && <LockIcon />}
                </button>
                {!isPremium && <div className="absolute bottom-full mb-2 hidden group-hover:block w-max bg-slate-800 text-white text-xs rounded py-1 px-2 z-10">{t('stats.unlockPremium')}</div>}
            </div>
           ))}
        </div>
      </div>

      <div className="space-y-4">
        {userStats.length > 0 ? userStats.map((user, index) => (
          <div key={user.id} className="bg-white dark:bg-slate-800/50 p-4 rounded-xl shadow-md flex items-center space-x-4 transition-transform duration-300 hover:scale-[1.02] hover:shadow-lg">
            <div className="flex items-center justify-center w-12 h-12 text-2xl font-bold">
              {index < 3 ? <TrophyIcon colorClass={rankingColors[index]} /> : <span className="text-slate-400 dark:text-slate-500">{index + 1}</span>}
            </div>
            {/* Avatar oculto pero mantenido en el DOM */}
            <img 
              src={user.avatar || '/user.svg'} 
              alt={user.name} 
              className="hidden" 
              onError={(e) => {
                const target = e.target as HTMLImageElement;
                target.onerror = null;
                target.src = '/user.svg';
              }}
            />
            <div className="flex-grow">
              <div className="flex items-center gap-2">
                <h3 className="text-xl font-bold text-slate-800 dark:text-slate-100">{user.name}</h3>
                {!user.isCurrentMember && (
                  <span className="text-xs font-medium px-2 py-1 bg-amber-100 dark:bg-amber-900/30 text-amber-800 dark:text-amber-400 rounded-full">
                    {t('stats.user.notInHome')}
                  </span>
                )}
              </div>
              <p className="text-sm text-slate-500 dark:text-slate-400">
                {t('stats.tasksCompleted', { count: user.stats.tasksCompleted })}
              </p>
            </div>
            <div className="text-right">
              <p className="text-3xl font-bold text-primary-500 dark:text-primary-400">{user.stats.pointsEarned}</p>
              <p className="text-sm text-slate-500 dark:text-slate-400">{t('stats.points')}</p>
            </div>
          </div>
        )) : (
            <div className="text-center py-20 text-slate-500 dark:text-slate-400">
                <p>{t('stats.empty.title')}</p>
                <p className="text-sm mt-2">{t('stats.empty.subtitle')}</p>
            </div>
        )}
      </div>
    </div>
  );
};

export default StatsPage;
