import { Periodicity, Task, TaskReminder, TaskStatus } from '../types';

type LocalNotificationPermission = 'granted' | 'denied' | 'prompt';

interface RuntimeLocalNotificationsPlugin {
  checkPermissions?: () => Promise<{ display?: LocalNotificationPermission }>;
  requestPermissions?: () => Promise<{ display?: LocalNotificationPermission }>;
  schedule?: (options: { notifications: Array<any> }) => Promise<any>;
  cancel?: (options: { notifications: Array<{ id: number }> }) => Promise<any>;
}

type ReminderIndexMap = Record<string, number[]>;

const REMINDER_INDEX_STORAGE_KEY = 'housezen_task_reminder_index_v1';
const MAX_NOTIFICATIONS_PER_TASK = 64;

class TaskReminderService {
  private permissionGranted: boolean | null = null;
  private webTimers = new Map<number, number>();

  private getRuntimePlugin(): RuntimeLocalNotificationsPlugin | null {
    if (typeof window === 'undefined') return null;
    const runtime = (window as any).Capacitor;
    if (!runtime?.Plugins?.LocalNotifications) return null;
    return runtime.Plugins.LocalNotifications as RuntimeLocalNotificationsPlugin;
  }

  private getPeriodicIntervalDays(task: Task): number {
    switch (task.periodicity) {
      case Periodicity.WEEKLY:
        return 7;
      case Periodicity.MONTHLY:
        return 30;
      case Periodicity.CUSTOM_DAYS:
        return Math.max(1, task.customDays || 1);
      case Periodicity.DAILY:
      default:
        return 1;
    }
  }

  private toMinutes(reminder: TaskReminder): number {
    switch (reminder.unit) {
      case 'days':
        return reminder.amount * 24 * 60;
      case 'hours':
        return reminder.amount * 60;
      case 'minutes':
      default:
        return reminder.amount;
    }
  }

  private normalizeReminder(reminder?: TaskReminder | null): TaskReminder | null {
    if (!reminder?.enabled) return null;
    const amount = Math.max(1, Number.isFinite(reminder.amount) ? Math.floor(reminder.amount) : 0);
    if (amount <= 0) return null;
    const unit = reminder.unit || 'minutes';
    return {
      enabled: true,
      amount,
      unit,
    };
  }

  private buildNotificationId(seed: string): number {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
      hash = (hash << 5) - hash + seed.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash % 2147480000) + 1000;
  }

  private formatReminderLead(reminder: TaskReminder): string {
    const unitLabel =
      reminder.unit === 'days'
        ? reminder.amount === 1
          ? 'día'
          : 'días'
        : reminder.unit === 'hours'
          ? reminder.amount === 1
            ? 'hora'
            : 'horas'
          : reminder.amount === 1
            ? 'minuto'
            : 'minutos';

    return `${reminder.amount} ${unitLabel}`;
  }

  private resolvePeriodicOccurrenceDate(task: Task, dayKey: string, dayInfo: any): Date | null {
    if (dayInfo?.date) {
      const parsedDate = new Date(dayInfo.date);
      if (!isNaN(parsedDate.getTime())) {
        return parsedDate;
      }
    }

    const startDate = new Date(task.fechaInicio || task.dueDate);
    if (isNaN(startDate.getTime())) {
      return null;
    }

    if (typeof dayInfo?.day === 'number') {
      const occurrence = new Date(startDate);
      occurrence.setDate(occurrence.getDate() + dayInfo.day);
      return occurrence;
    }

    const parsedDayKey = Number.parseInt(dayKey, 10);
    if (!Number.isNaN(parsedDayKey)) {
      const intervalDays = this.getPeriodicIntervalDays(task);
      const occurrence = new Date(startDate);
      occurrence.setDate(occurrence.getDate() + parsedDayKey * intervalDays);
      return occurrence;
    }

    return null;
  }

  private getTaskOccurrences(task: Task): Array<{ key: string; date: Date; status: TaskStatus }> {
    if (task.periodicity !== Periodicity.NONE && task.registroDetallado && Object.keys(task.registroDetallado).length > 0) {
      const occurrences = Object.entries(task.registroDetallado)
        .map(([dayKey, dayInfo]) => {
          const date = this.resolvePeriodicOccurrenceDate(task, dayKey, dayInfo);
          if (!date || isNaN(date.getTime())) return null;
          return {
            key: dayKey,
            date,
            status: (dayInfo.status as TaskStatus) || TaskStatus.PENDING,
          };
        })
        .filter((item): item is { key: string; date: Date; status: TaskStatus } => !!item)
        .sort((a, b) => a.date.getTime() - b.date.getTime());

      return occurrences;
    }

    const rootDueDate = new Date(task.dueDate);
    if (isNaN(rootDueDate.getTime())) return [];
    return [
      {
        key: 'root',
        date: rootDueDate,
        status: task.status,
      },
    ];
  }

  private loadReminderIndex(): ReminderIndexMap {
    if (typeof window === 'undefined') return {};
    try {
      const raw = localStorage.getItem(REMINDER_INDEX_STORAGE_KEY);
      if (!raw) return {};
      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return {};
      return parsed as ReminderIndexMap;
    } catch {
      return {};
    }
  }

  private saveReminderIndex(index: ReminderIndexMap): void {
    if (typeof window === 'undefined') return;
    try {
      localStorage.setItem(REMINDER_INDEX_STORAGE_KEY, JSON.stringify(index));
    } catch {
      // No-op: evitar romper UX por errores de almacenamiento local.
    }
  }

  private clearWebTimer(id: number): void {
    const timerId = this.webTimers.get(id);
    if (timerId !== undefined) {
      window.clearTimeout(timerId);
      this.webTimers.delete(id);
    }
  }

  private async ensurePermission(plugin: RuntimeLocalNotificationsPlugin | null): Promise<boolean> {
    if (this.permissionGranted !== null) return this.permissionGranted;

    if (plugin?.checkPermissions || plugin?.requestPermissions) {
      try {
        const checkResult = await plugin.checkPermissions?.();
        let displayPermission = checkResult?.display;

        if (displayPermission !== 'granted' && plugin.requestPermissions) {
          const requestResult = await plugin.requestPermissions();
          displayPermission = requestResult?.display;
        }

        this.permissionGranted = displayPermission === 'granted';
        return this.permissionGranted;
      } catch (error) {
        console.warn('[taskReminderService] Error verificando permisos LocalNotifications:', error);
        this.permissionGranted = false;
        return false;
      }
    }

    if (typeof Notification !== 'undefined') {
      if (Notification.permission === 'granted') {
        this.permissionGranted = true;
        return true;
      }

      if (Notification.permission === 'default') {
        try {
          const permission = await Notification.requestPermission();
          this.permissionGranted = permission === 'granted';
          return this.permissionGranted;
        } catch {
          this.permissionGranted = false;
          return false;
        }
      }
    }

    this.permissionGranted = false;
    return false;
  }

  async cancelTaskReminders(taskId: string): Promise<void> {
    const plugin = this.getRuntimePlugin();
    const index = this.loadReminderIndex();
    const ids = index[taskId] || [];

    if (ids.length === 0) return;

    for (const id of ids) {
      this.clearWebTimer(id);
    }

    if (plugin?.cancel) {
      try {
        await plugin.cancel({ notifications: ids.map((id) => ({ id })) });
      } catch (error) {
        console.warn('[taskReminderService] Error cancelando recordatorios locales:', error);
      }
    }

    delete index[taskId];
    this.saveReminderIndex(index);
  }

  async scheduleTaskReminders(task: Task): Promise<void> {
    const reminder = this.normalizeReminder(task.reminder);

    // Si el recordatorio está desactivado o inválido, cancelar cualquier programación previa.
    if (!reminder) {
      await this.cancelTaskReminders(task.id);
      return;
    }

    if (task.periodicity === Periodicity.NONE && task.status === TaskStatus.COMPLETED) {
      await this.cancelTaskReminders(task.id);
      return;
    }

    const plugin = this.getRuntimePlugin();
    const hasPermission = await this.ensurePermission(plugin);
    if (!hasPermission) {
      return;
    }

    await this.cancelTaskReminders(task.id);

    const minutesBefore = this.toMinutes(reminder);
    const now = Date.now();
    const occurrences = this.getTaskOccurrences(task);
    const notifications: Array<{
      id: number;
      title: string;
      body: string;
      triggerAt: Date;
    }> = [];

    for (const occurrence of occurrences) {
      if (occurrence.status === TaskStatus.DELETED || occurrence.status === TaskStatus.COMPLETED) {
        continue;
      }

      const triggerAt = new Date(occurrence.date.getTime() - minutesBefore * 60 * 1000);
      if (triggerAt.getTime() <= now) continue;

      const id = this.buildNotificationId(`${task.id}:${occurrence.key}:${minutesBefore}`);
      notifications.push({
        id,
        title: 'Recordatorio de tarea',
        body: `La tarea "${task.title}" vence en ${this.formatReminderLead(reminder)}.`,
        triggerAt,
      });

      if (notifications.length >= MAX_NOTIFICATIONS_PER_TASK) break;
    }

    if (notifications.length === 0) {
      return;
    }

    const index = this.loadReminderIndex();
    index[task.id] = notifications.map((n) => n.id);
    this.saveReminderIndex(index);

    if (plugin?.schedule) {
      try {
        await plugin.schedule({
          notifications: notifications.map((n) => ({
            id: n.id,
            title: n.title,
            body: n.body,
            schedule: { at: n.triggerAt, allowWhileIdle: true },
            extra: {
              taskId: task.id,
            },
          })),
        });
        return;
      } catch (error) {
        console.warn('[taskReminderService] Error programando recordatorios locales nativos:', error);
      }
    }

    // Fallback web (solo en sesión activa; en móvil nativo se prioriza plugin).
    if (typeof Notification !== 'undefined' && Notification.permission === 'granted') {
      notifications.forEach((n) => {
        const delay = n.triggerAt.getTime() - Date.now();
        if (delay <= 0 || delay > 2147483647) return;
        const timerId = window.setTimeout(() => {
          new Notification(n.title, { body: n.body });
          this.webTimers.delete(n.id);
        }, delay);
        this.webTimers.set(n.id, timerId);
      });
    }
  }

  async syncTaskReminders(tasks: Task[]): Promise<void> {
    const taskIds = new Set(tasks.map((task) => task.id));
    const index = this.loadReminderIndex();

    const staleTaskIds = Object.keys(index).filter((taskId) => !taskIds.has(taskId));
    for (const staleTaskId of staleTaskIds) {
      await this.cancelTaskReminders(staleTaskId);
    }

    for (const task of tasks) {
      await this.scheduleTaskReminders(task);
    }
  }
}

export const taskReminderService = new TaskReminderService();
