/**
 * DataServiceRouter
 * Selecciona servicio de datos:
 * - Local por defecto (anónimo / sin premium activo).
 * - Firebase cuando el usuario tiene premium activo o cuando es invitado de una casa cloud.
 */

import { IDataService } from './data.interface';
import { localDataService } from './localDataService';
import { firebaseDataService } from './firebaseDataService';
import { Home, HomeInvitation, JoinHomeByInviteOptions, JoinHomeInvitePreview, Reward, RewardClaim, Task, User } from '../types';
import { auth, db } from './firebase';
import {
  collection,
  doc,
  getDoc,
  getDocs,
  query,
  setDoc,
  where,
} from 'firebase/firestore';

type LocalExportSnapshot = {
  users: User[];
  homes: Home[];
  tasks: Task[];
  invitations: HomeInvitation[];
  rewards: Reward[];
  rewardClaims: RewardClaim[];
  loggedInUser?: User | null;
};

class DataServiceRouter {
  private static instance: DataServiceRouter;
  private currentService: IDataService = localDataService;
  private currentUser: User | null = null;
  private changeCallbacks: Array<() => void> = [];

  private constructor() {}

  static getInstance(): DataServiceRouter {
    if (!DataServiceRouter.instance) {
      DataServiceRouter.instance = new DataServiceRouter();
    }
    return DataServiceRouter.instance;
  }

  getService(): IDataService {
    return this.currentService;
  }

  getCurrentUser(): User | null {
    return this.currentUser;
  }

  isUserRegistered(): boolean {
    return this.currentUser ? !!this.currentUser.email : false;
  }

  isUsingLocalService(): boolean {
    return this.currentService === localDataService;
  }

  isUsingFirebaseService(): boolean {
    return this.currentService === firebaseDataService;
  }

  switchToLocal(): void {
    if (this.currentService === localDataService) return;
    this.currentService = localDataService;
    this.emitChange();
  }

  switchToFirebase(): void {
    if (this.currentService === firebaseDataService) return;
    this.currentService = firebaseDataService;
    this.emitChange();
  }

  private isPremiumCloudActive(user: User | null): boolean {
    if (!user) return false;
    if (user.plan !== 'premium') return false;
    const status = String(user.subscriptionStatus || 'active');
    return status === 'active' || status === 'cancel_at_period_end';
  }

  private hasAnonymousCloudAccess(user: User | null): boolean {
    if (!user) return false;
    return Boolean(user.allowCloudAccess);
  }

  private getHomeOwnerId(home: Partial<Home>): string | undefined {
    return home.createdBy || home.adminIds?.[0];
  }

  private sanitize<T>(value: T): T {
    if (value === null || value === undefined) return value;
    if (Array.isArray(value)) {
      return value.map((item) => this.sanitize(item)) as unknown as T;
    }
    if (typeof value === 'object') {
      const source = value as Record<string, unknown>;
      const output: Record<string, unknown> = {};
      Object.keys(source).forEach((key) => {
        const v = source[key];
        if (v !== undefined) {
          output[key] = this.sanitize(v);
        }
      });
      return output as T;
    }
    return value;
  }

  private hasLocalHomesForUser(userId: string): boolean {
    try {
      const exported = localDataService.exportDatabase();
      const snapshot = JSON.parse(exported || '{}') as LocalExportSnapshot;
      const homes = Array.isArray(snapshot.homes) ? snapshot.homes : [];
      return homes.some((home) => Array.isArray(home.memberIds) && home.memberIds.includes(userId));
    } catch (error) {
      console.warn('[DataServiceRouter] No se pudo inspeccionar el fallback local:', error);
      return false;
    }
  }

  private async shouldUseFirebaseForNonPremium(user: User): Promise<boolean> {
    if (this.hasAnonymousCloudAccess(user)) return true;
    if (!user.email) return false;
    const uid = user.id;

    // 1) Si es miembro de casas cloud y NO es propietario de alguna de ellas, mantiene acceso cloud.
    let homesSnap;
    try {
      homesSnap = await getDocs(
        query(collection(db, 'homes'), where('memberIds', 'array-contains', uid))
      );
    } catch (error: any) {
      const code = String(error?.code || '');
      if (code.includes('permission-denied')) {
        // Sin permisos cloud: volver silenciosamente a local.
        return false;
      }
      throw error;
    }

    if (!homesSnap.empty) {
      const ownsAnyHome = homesSnap.docs.some((homeDoc) => {
        const ownerId = this.getHomeOwnerId(homeDoc.data() as Partial<Home>);
        return ownerId === uid;
      });
      if (!ownsAnyHome) return true;

      // Si el usuario es propietario pero no hay copia local de sus casas,
      // mantenemos cloud para evitar mostrar "sin casa activa" tras el login.
      if (!this.hasLocalHomesForUser(uid)) {
        return true;
      }

      return false;
    }

    // 2) Ya no usamos invitaciones por email: si no tiene casas cloud, vuelve a local.
    return false;
  }

  updateUser(user: User | null): void {
    this.currentUser = user;

    if (!user) {
      this.switchToLocal();
      return;
    }

    const isAnonymousOrEmailless = !user.email || user.isAnonymous;
    const hasAnonymousCloudAccess = this.hasAnonymousCloudAccess(user);

    if (isAnonymousOrEmailless && !hasAnonymousCloudAccess) {
      this.switchToLocal();
      return;
    }

    if (isAnonymousOrEmailless && hasAnonymousCloudAccess) {
      if (auth.currentUser?.uid === user.id) {
        this.switchToFirebase();
      } else {
        this.switchToLocal();
      }
      return;
    }

    // Solo consideramos sesión cloud válida cuando coincide con auth actual.
    if (auth.currentUser?.uid !== user.id) {
      this.switchToLocal();
      return;
    }

    if (this.isPremiumCloudActive(user)) {
      this.switchToFirebase();
      return;
    }

    // Usuario autenticado sin premium activo: decidir si se queda en cloud (invitado) o vuelve a local (propietario/no miembro).
    void this.shouldUseFirebaseForNonPremium(user)
      .then((shouldUseFirebase) => {
        // Evitar carreras si cambió usuario durante la consulta.
        if (!this.currentUser || this.currentUser.id !== user.id) return;
        if (shouldUseFirebase) {
          this.switchToFirebase();
        } else {
          void this.ensureLocalFallbackUserFromCloud(user).finally(() => {
            this.switchToLocal();
          });
        }
      })
      .catch((error) => {
        // Mantener fallback local siempre que falle la evaluación cloud.
        if (typeof console !== 'undefined' && typeof console.warn === 'function') {
          console.warn('[DataServiceRouter] Fallback local al evaluar modo de datos:', error);
        }
        this.switchToLocal();
      });
  }

  async syncWithFirebaseAuthContext(): Promise<void> {
    if (!auth.currentUser) return;

    try {
      const userRef = doc(db, 'users', auth.currentUser.uid);
      const userSnap = await getDoc(userRef);
      if (!userSnap.exists()) return;

      const firebaseUser = {
        id: auth.currentUser.uid,
        ...userSnap.data(),
      } as User;

      this.updateUser(firebaseUser);
    } catch (error) {
      console.error('[DataServiceRouter] Error sincronizando contexto auth Firebase:', error);
    }
  }

  private async migrateLocalDataToFirebase(uid: string): Promise<{ success: boolean; message: string }> {
    try {
      const raw = localDataService.exportDatabase();
      const snapshot = JSON.parse(raw || '{}') as LocalExportSnapshot;

      const users = snapshot.users || [];
      const homes = snapshot.homes || [];
      const tasks = snapshot.tasks || [];
      const invitations = snapshot.invitations || [];
      const rewards = snapshot.rewards || [];
      const rewardClaims = snapshot.rewardClaims || [];
      const loggedInUser = snapshot.loggedInUser || null;

      const localOwnerId =
        loggedInUser?.id ||
        users.find((u) => !!u.email && u.email === auth.currentUser?.email)?.id ||
        null;

      const mapUserId = (id?: string | null): string | null => {
        if (!id) return null;
        if (localOwnerId && id === localOwnerId) return uid;
        return id;
      };

      // Asegurar documento base del usuario autenticado cloud.
      const authUser = auth.currentUser;
      await setDoc(
        doc(db, 'users', uid),
        this.sanitize({
          email: authUser?.email?.toLowerCase() || null,
          plan: 'premium',
          updatedAt: new Date().toISOString(),
          localDataMigratedAt: new Date().toISOString(),
        }),
        { merge: true }
      );

      // Subir perfiles locales anónimos/no propietarios para poder vincularlos
      // posteriormente cuando un invitado se una por URL.
      for (const localUser of users) {
        const mappedUserId = mapUserId(localUser.id);
        if (!mappedUserId) continue;

        if (mappedUserId === uid) {
          await setDoc(
            doc(db, 'users', uid),
            this.sanitize({
              name: localUser.name || authUser?.displayName || 'Usuario',
              avatar: localUser.avatar || authUser?.photoURL || '/user.svg',
              color: localUser.color || '#3b82f6',
              plan: localUser.plan || 'premium',
            }),
            { merge: true }
          );
          continue;
        }

        const anonymousProfile = this.sanitize({
          name: localUser.name || 'Miembro',
          email: null,
          avatar: localUser.avatar || '/user.svg',
          color: localUser.color || '#3b82f6',
          plan: 'free',
          isAnonymous: true,
          allowCloudAccess: false,
          createdAt: localUser.createdAt || new Date().toISOString(),
          migratedFromLocal: true,
        });

        await setDoc(doc(db, 'users', mappedUserId), anonymousProfile, { merge: true });
      }

      for (const home of homes) {
        const mappedAdminIds = (home.adminIds || [])
          .map((id) => mapUserId(id))
          .filter((id): id is string => !!id);
        const mappedMemberIds = (home.memberIds || [])
          .map((id) => mapUserId(id))
          .filter((id): id is string => !!id);

        const ownerId =
          mapUserId(home.createdBy) ||
          mappedAdminIds[0] ||
          uid;

        const homePayload: Partial<Home> = this.sanitize({
          ...home,
          createdBy: ownerId,
          adminIds: Array.from(new Set(mappedAdminIds.length ? mappedAdminIds : [uid])),
          memberIds: Array.from(new Set(mappedMemberIds.length ? mappedMemberIds : [uid])),
          mode: 'PREMIUM',
        });

        await setDoc(doc(db, 'homes', home.id), homePayload as Home, { merge: true });
      }

      for (const task of tasks) {
        const mappedRegistroDetallado = task.registroDetallado
          ? Object.fromEntries(
              Object.entries(task.registroDetallado).map(([dayKey, dayValue]) => [
                dayKey,
                {
                  ...dayValue,
                  assignedTo: mapUserId(dayValue.assignedTo || null),
                  completedBy: mapUserId(dayValue.completedBy || null),
                },
              ])
            )
          : undefined;

        const taskPayload: Partial<Task> = this.sanitize({
          ...task,
          createdBy: mapUserId(task.createdBy) || uid,
          assignedTo: mapUserId(task.assignedTo || null),
          completedBy: mapUserId(task.completedBy || null),
          registroDetallado: mappedRegistroDetallado,
        });
        await setDoc(doc(db, 'tasks', task.id), taskPayload as Task, { merge: true });
      }

      for (const invitation of invitations) {
        const invitationPayload: Partial<HomeInvitation> = this.sanitize({
          ...invitation,
          invitedBy: mapUserId(invitation.invitedBy) || uid,
          inviteeEmail: invitation.inviteeEmail?.toLowerCase() || '',
        });
        await setDoc(doc(db, 'invitations', invitation.id), invitationPayload as HomeInvitation, { merge: true });
      }

      for (const reward of rewards) {
        const rewardPayload: Partial<Reward> = this.sanitize({
          ...reward,
          createdBy: mapUserId(reward.createdBy) || uid,
        });
        await setDoc(doc(db, 'rewards', reward.id), rewardPayload as Reward, { merge: true });
      }

      for (const claim of rewardClaims) {
        const claimPayload: Partial<RewardClaim> = this.sanitize({
          ...claim,
          userId: mapUserId(claim.userId) || uid,
          processedBy: mapUserId(claim.processedBy || null),
        });
        await setDoc(doc(db, 'rewardClaims', claim.id), claimPayload as RewardClaim, { merge: true });
      }

      return {
        success: true,
        message: 'Datos locales sincronizados en la nube correctamente.',
      };
    } catch (error: any) {
      console.error('[DataServiceRouter] Error migrando datos locales a Firebase:', error);
      return {
        success: false,
        message: error?.message || 'No se pudieron sincronizar los datos locales con la nube.',
      };
    }
  }

  private async ensureLocalFallbackUserFromCloud(cloudUser: User): Promise<void> {
    try {
      const exported = localDataService.exportDatabase();
      const snapshot = JSON.parse(exported || '{}') as LocalExportSnapshot;
      const hasUsers = Array.isArray(snapshot.users) && snapshot.users.length > 0;
      if (hasUsers) return;

      const localAnonymousUser: User = {
        id: cloudUser.id,
        name: cloudUser.name || 'Usuario',
        email: undefined,
        avatar: cloudUser.avatar || '/user.svg',
        color: cloudUser.color || '#3b82f6',
        plan: 'free',
        isAnonymous: true,
      };

      const fallbackSnapshot: LocalExportSnapshot = {
        users: [localAnonymousUser],
        homes: [],
        tasks: [],
        invitations: [],
        rewards: [],
        rewardClaims: [],
        loggedInUser: localAnonymousUser,
      };

      await localDataService.importDatabase(JSON.stringify(fallbackSnapshot));
    } catch (error) {
      console.error('[DataServiceRouter] Error creando usuario local fallback:', error);
    }
  }

  async activatePremiumCloudMode(): Promise<{ success: boolean; message: string }> {
    if (!auth.currentUser) {
      return {
        success: false,
        message: 'Debes iniciar sesión para activar sincronización en la nube.',
      };
    }

    const uid = auth.currentUser.uid;
    const userRef = doc(db, 'users', uid);
    const userSnap = await getDoc(userRef);

    if (!userSnap.exists()) {
      return {
        success: false,
        message: 'No se encontró el perfil de usuario en la nube.',
      };
    }

    const cloudUser = {
      id: uid,
      ...userSnap.data(),
    } as User;

    if (!this.isPremiumCloudActive(cloudUser)) {
      return {
        success: false,
        message: 'Tu suscripción premium aún no está activa.',
      };
    }

    const migration = await this.migrateLocalDataToFirebase(uid);
    if (!migration.success) {
      return migration;
    }

    this.currentUser = cloudUser;
    this.switchToFirebase();
    return {
      success: true,
      message: 'Modo premium activado. Ahora tus datos se guardan en la nube.',
    };
  }

  async createHomeInviteLink(homeId: string): Promise<{ success: boolean; message: string; inviteUrl?: string }> {
    const service = this.getService();
    if (!service.createHomeInviteLink) {
      return {
        success: false,
        message: 'La creación de enlaces de invitación no está disponible en este modo.',
      };
    }
    return service.createHomeInviteLink(homeId);
  }

  async getJoinHomeInviteOptions(token: string): Promise<JoinHomeInvitePreview> {
    if (!firebaseDataService.getJoinHomeInviteOptions) {
      return {
        success: false,
        message: 'La vista previa de invitación no está disponible temporalmente.',
      };
    }
    return firebaseDataService.getJoinHomeInviteOptions(token);
  }

  async joinHomeByInviteToken(token: string, options?: JoinHomeByInviteOptions): Promise<{ success: boolean; message: string; homeId?: string }> {
    if (!firebaseDataService.joinHomeByInviteToken) {
      return {
        success: false,
        message: 'La unión por enlace no está disponible temporalmente.',
      };
    }

    const result = await firebaseDataService.joinHomeByInviteToken(token, options);
    if (result.success) {
      await this.syncWithFirebaseAuthContext();
      this.switchToFirebase();
    }
    return result;
  }

  onChange(cb: () => void) {
    this.changeCallbacks.push(cb);
    return () => {
      this.changeCallbacks = this.changeCallbacks.filter((c) => c !== cb);
    };
  }

  private emitChange() {
    this.changeCallbacks.forEach((cb) => {
      try {
        cb();
      } catch (e) {
        console.error('dataServiceRouter onChange callback error', e);
      }
    });
  }
}

export const dataServiceRouter = DataServiceRouter.getInstance();
