import React, { useEffect, useMemo, useState } from 'react';
import { View } from '../types';
import { usePlatform } from '../hooks/usePlatform';
import { useData } from '../hooks/useData';
import { CheckCircleIcon } from './Icons';
import { loadStripe } from '@stripe/stripe-js';
import { useAuthState } from 'react-firebase-hooks/auth';
import { auth, functions } from '../services/firebase';
import { STRIPE_CONFIG } from '../stripe.config.js';
import { googlePlayBillingService, GOOGLE_PLAY_PRODUCTS, GooglePlayProduct } from '../services/googlePlayBillingService';
import { appleBillingService, APPLE_PRODUCTS, AppleBillingProduct } from '../services/appleBillingService';
import { httpsCallable } from 'firebase/functions';
import { useSubscription } from '../hooks/useSubscription';
import { useAppConfig } from '../hooks/useAppConfig';
import { useI18n } from '../i18n/I18nProvider';
import { isPremiumPurchaseEnabledForPlatform } from '../services/appConfigService';

interface SubscriptionPageProps {
  onViewChange: (view: View) => void;
  onRequireAccount: () => void;
}

const LANGUAGE_TO_LOCALE: Record<string, string> = {
  es: 'es-ES',
  en: 'en-US',
  ca: 'ca-ES',
  fr: 'fr-FR',
  pt: 'pt-PT',
};

const formatCurrencyLabel = (
  amount: number,
  currencyCode: string | undefined,
  locale: string
): string | null => {
  if (!Number.isFinite(amount) || amount < 0 || !currencyCode) return null;

  try {
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: currencyCode.toUpperCase(),
    }).format(amount);
  } catch {
    return null;
  }
};

const parseAdminPriceLabel = (label: string): { amount: number; currencyCode?: string } | null => {
  if (!label) return null;

  const normalized = label.trim();
  const numberMatch = normalized.replace(/\s/g, '').match(/-?\d[\d.,]*/);
  if (!numberMatch) return null;

  let numeric = numberMatch[0];
  const lastComma = numeric.lastIndexOf(',');
  const lastDot = numeric.lastIndexOf('.');

  if (lastComma > -1 && lastDot > -1) {
    const decimalSeparator = lastComma > lastDot ? ',' : '.';
    const thousandsSeparator = decimalSeparator === ',' ? '.' : ',';
    numeric = numeric.replace(new RegExp(`\\${thousandsSeparator}`, 'g'), '');
    if (decimalSeparator === ',') numeric = numeric.replace(',', '.');
  } else if (lastComma > -1) {
    const parts = numeric.split(',');
    if (parts.length > 2) {
      const decimalPart = parts.pop() || '';
      numeric = `${parts.join('')}.${decimalPart}`;
    } else if ((parts[1] || '').length <= 2) {
      numeric = `${parts[0]}.${parts[1] || ''}`;
    } else {
      numeric = parts.join('');
    }
  } else if (lastDot > -1) {
    const parts = numeric.split('.');
    if (parts.length > 2) {
      const decimalPart = parts.pop() || '';
      numeric = `${parts.join('')}.${decimalPart}`;
    } else if ((parts[1] || '').length > 2) {
      numeric = parts.join('');
    }
  }

  const amount = Number(numeric);
  if (!Number.isFinite(amount)) return null;

  const currencyCodeMatch = normalized.toUpperCase().match(/\b([A-Z]{3})\b/);
  const currencyCode = currencyCodeMatch?.[1]
    || (normalized.includes('€') ? 'EUR' : undefined)
    || (normalized.includes('£') ? 'GBP' : undefined)
    || (normalized.includes('¥') ? 'JPY' : undefined)
    || (normalized.includes('R$') ? 'BRL' : undefined)
    || (normalized.includes('$') ? 'USD' : undefined);

  return { amount, currencyCode };
};

const localizeAdminPriceLabel = (label: string, locale: string): string => {
  const parsed = parseAdminPriceLabel(label);
  if (!parsed) return label;

  const localized = formatCurrencyLabel(parsed.amount, parsed.currencyCode, locale);
  return localized || label;
};

const SubscriptionPage: React.FC<SubscriptionPageProps> = ({ onViewChange, onRequireAccount }) => {
  const { t, language } = useI18n();
  const { platform } = usePlatform();
  const { appConfig } = useAppConfig();
  const [firebaseUser] = useAuthState(auth);
  const data = useData();
  const { isPremium, subscriptionStatus } = useSubscription(
    data.currentUser,
    data.userHomes,
    data.currentHome,
    data.tasks
  );

  const [loading, setLoading] = useState(false);
  const [googlePlayProducts, setGooglePlayProducts] = useState<GooglePlayProduct[]>([]);
  const [appleProducts, setAppleProducts] = useState<AppleBillingProduct[]>([]);
  const [billingReady, setBillingReady] = useState(false);
  const [billingError, setBillingError] = useState<string | null>(null);
  const [alreadyPremiumByEmail, setAlreadyPremiumByEmail] = useState(false);
  const [syncMessage, setSyncMessage] = useState<string | null>(null);
  const [restoringAccess, setRestoringAccess] = useState(false);
  const [trialLoading, setTrialLoading] = useState(false);

  const priceIds = {
    monthly: STRIPE_CONFIG.prices.premium_monthly,
    yearly: STRIPE_CONFIG.prices.premium_yearly,
  };

  const runtimePlatform = useMemo<'web' | 'android' | 'ios'>(() => {
    const cap = (typeof window !== 'undefined') ? (window as any).Capacitor : null;
    if (cap?.isNativePlatform?.()) {
      const capPlatform = cap.getPlatform?.();
      if (capPlatform === 'android' || capPlatform === 'ios') return capPlatform;
    }
    return platform;
  }, [platform]);

  const preferredLocale = useMemo(() => {
    const languageLocale = LANGUAGE_TO_LOCALE[language];
    if (languageLocale) return languageLocale;
    if (typeof navigator !== 'undefined' && navigator.language) return navigator.language;
    return 'es-ES';
  }, [language]);

  const nativeBillingRequiresReady = runtimePlatform === 'android' || runtimePlatform === 'ios';
  const purchaseEnabledOnPlatform = isPremiumPurchaseEnabledForPlatform(appConfig, runtimePlatform);

  const canPurchase = useMemo(() => {
    if (!firebaseUser || !firebaseUser.email) return false;
    if (loading) return false;
    if (isPremium || alreadyPremiumByEmail) return false;
    if (!purchaseEnabledOnPlatform) return false;
    return true;
  }, [firebaseUser, loading, isPremium, alreadyPremiumByEmail, purchaseEnabledOnPlatform]);

  const canStartTrial = useMemo(() => {
    if (trialLoading || loading) return false;
    if (isPremium || alreadyPremiumByEmail) return false;
    if (!purchaseEnabledOnPlatform) return false;
    return true;
  }, [trialLoading, loading, isPremium, alreadyPremiumByEmail, purchaseEnabledOnPlatform]);

  const premiumFeatures = [
    { icon: '☁️', text: t('subscription.feature.cloud') },
    { icon: '🤝', text: t('subscription.feature.shareHome') },
    { icon: '🔄', text: t('subscription.feature.syncDevices') },
    { icon: '🏠', text: t('subscription.feature.homes') },
    { icon: '👨‍👩‍👧‍👦', text: t('subscription.feature.members') },
    { icon: '✅', text: t('subscription.feature.tasks') },
    { icon: '🗂️', text: t('subscription.feature.history') },
    { icon: '📈', text: t('subscription.feature.stats') },
    { icon: '🏆', text: t('subscription.feature.rewards') },
    { icon: '🔁', text: t('subscription.feature.periodic') },
  ];

  useEffect(() => {
    if (runtimePlatform === 'android') {
      void initializeGooglePlayBilling();
    }
    if (runtimePlatform === 'ios') {
      void initializeAppleBilling();
    }
  }, [runtimePlatform]);

  const initializeGooglePlayBilling = async () => {
    try {
      if (!googlePlayBillingService.isAvailable()) return;
      await googlePlayBillingService.initialize();
      const products = await googlePlayBillingService.queryProducts(Object.values(GOOGLE_PLAY_PRODUCTS));
      setGooglePlayProducts(products);
      setBillingReady(true);
    } catch (error) {
      console.error('[SubscriptionPage] Error Google Play Billing:', error);
    }
  };

  const initializeAppleBilling = async () => {
    try {
      if (!appleBillingService.isAvailable()) {
        setBillingError('Apple Billing no está disponible en esta build iOS.');
        return;
      }
      const products = await appleBillingService.queryProducts(Object.values(APPLE_PRODUCTS));
      if (!products.length) {
        setBillingError('No se encontraron productos de suscripción en App Store Connect.');
        return;
      }
      setBillingError(null);
      setAppleProducts(products);
      setBillingReady(true);
    } catch (error) {
      console.error('[SubscriptionPage] Error Apple Billing:', error);
      setBillingError('No se pudieron cargar los productos de Apple. Revisa App Store Connect e identificadores.');
    }
  };

  const checkAlreadyPremiumBeforePurchase = async (): Promise<boolean> => {
    if (isPremium || alreadyPremiumByEmail) {
      alert(t('subscription.alert.alreadyActive'));
      return true;
    }

    try {
      const syncFn = httpsCallable(functions, 'syncSubscriptionByEmail');
      const result = await syncFn({});
      const payload = result.data as any;
      if (payload?.hasActiveSubscription) {
        setAlreadyPremiumByEmail(true);
        alert(t('subscription.alert.alreadyActiveEmail'));
        return true;
      }
    } catch (error) {
      console.error('[SubscriptionPage] Error verificando suscripción por email:', error);
    }

    return false;
  };

  const handleStripeSubscription = async (planType: 'monthly' | 'yearly') => {
    if (await checkAlreadyPremiumBeforePurchase()) return;

    setLoading(true);
    try {
      const stripe = await loadStripe(process.env.PARCEL_STRIPE_PUBLIC_KEY || '');
      if (!stripe) throw new Error('Stripe no se pudo cargar');

      const { error } = await stripe.redirectToCheckout({
        lineItems: [{ price: priceIds[planType], quantity: 1 }],
        mode: 'subscription',
        successUrl: `${window.location.origin}/success?session_id={CHECKOUT_SESSION_ID}&plan=${planType}`,
        cancelUrl: `${window.location.origin}/settings`,
        customerEmail: firebaseUser?.email || undefined,
        clientReferenceId: firebaseUser?.uid,
      });

      if (error) {
        console.error('[SubscriptionPage] Error Stripe:', error);
        alert(t('subscription.alert.stripeStartError'));
      }
    } catch (error) {
      console.error('[SubscriptionPage] Stripe error:', error);
      alert(t('subscription.alert.stripeProcessError'));
    } finally {
      setLoading(false);
    }
  };

  const handleGooglePlaySubscription = async (planType: 'monthly' | 'yearly') => {
    if (await checkAlreadyPremiumBeforePurchase()) return;

    setLoading(true);
    try {
      const productId = planType === 'monthly'
        ? GOOGLE_PLAY_PRODUCTS.premium_monthly_sub
        : GOOGLE_PLAY_PRODUCTS.premium_yearly_sub;

      const product = googlePlayProducts.find(p => p.productId === productId);
      if (!product) throw new Error('Producto de Google Play no encontrado');

      const purchase = await googlePlayBillingService.purchaseSubscription(productId);
      const verifyPurchase = httpsCallable(functions, 'verifyGooglePlayPurchase');
      await verifyPurchase({
        purchaseToken: purchase.purchaseToken,
        productId,
      });
      await googlePlayBillingService.acknowledgePurchase(purchase.purchaseToken);
      const cloudActivation = await data.activatePremiumCloudMode();
      if (!cloudActivation.success) {
        console.warn('[SubscriptionPage] Premium activo pero sin migración cloud completa:', cloudActivation.message);
      }
      alert(t('subscription.alert.activated'));
      onViewChange(View.DASHBOARD);
    } catch (error: any) {
      console.error('[SubscriptionPage] Google Play error:', error);
      if (error?.message !== 'Compra cancelada por el usuario') {
        alert(t('subscription.alert.googlePlayError'));
      }
    } finally {
      setLoading(false);
    }
  };

  const handleAppleSubscription = async (planType: 'monthly' | 'yearly') => {
    if (await checkAlreadyPremiumBeforePurchase()) return;

    setLoading(true);
    try {
      const productId = planType === 'monthly'
        ? APPLE_PRODUCTS.premium_monthly_sub
        : APPLE_PRODUCTS.premium_yearly_sub;

      const product = appleProducts.find(p => p.productId === productId);
      if (!product && appleBillingService.isAvailable()) {
        // permitimos continuar si el plugin soporta compra directa por ID
        console.warn('[SubscriptionPage] Producto iOS no precargado, intentando compra directa');
      }

      const purchase = await appleBillingService.purchaseSubscription(productId);
      const verifyApplePurchase = httpsCallable(functions, 'verifyApplePurchase');
      await verifyApplePurchase({
        transactionId: purchase.transactionId,
        originalTransactionId: purchase.originalTransactionId || null,
        productId: purchase.productId,
        purchaseDateMs: purchase.purchaseDateMs || null,
        expirationDateMs: purchase.expirationDateMs || null,
      });

      const cloudActivation = await data.activatePremiumCloudMode();
      if (!cloudActivation.success) {
        console.warn('[SubscriptionPage] Premium activo pero sin migración cloud completa:', cloudActivation.message);
      }
      alert(t('subscription.alert.activated'));
      onViewChange(View.DASHBOARD);
    } catch (error: any) {
      console.error('[SubscriptionPage] Apple Billing error:', error);
      if (String(error?.message || '').toLowerCase().includes('cancelada')) return;
      alert(t('subscription.alert.iosError'));
    } finally {
      setLoading(false);
    }
  };

  const handleSubscription = async (planType: 'monthly' | 'yearly') => {
    if (!purchaseEnabledOnPlatform) {
      alert(t('subscription.alert.purchaseDisabled'));
      return;
    }

    if (!firebaseUser || !firebaseUser.email) {
      const shouldOpenLogin = window.confirm(
        t('subscription.confirm.requireAccount')
      );
      if (shouldOpenLogin) {
        onRequireAccount();
      }
      return;
    }

    if (runtimePlatform === 'web') {
      await handleStripeSubscription(planType);
      return;
    }

    if (runtimePlatform === 'android') {
      await handleGooglePlaySubscription(planType);
      return;
    }

    if (runtimePlatform === 'ios') {
      await handleAppleSubscription(planType);
      return;
    }

    alert(t('subscription.alert.unsupportedPlatform'));
  };

  const handleRecoverPremiumAccess = async () => {
    if (!firebaseUser || !firebaseUser.email) {
      onRequireAccount();
      return;
    }

    setRestoringAccess(true);
    try {
      const syncFn = httpsCallable(functions, 'syncSubscriptionByEmail');
      const syncResult = await syncFn({});
      const syncPayload = syncResult.data as any;

      if (syncPayload?.hasActiveSubscription) {
        setAlreadyPremiumByEmail(true);
        setSyncMessage('Premium restaurado con tu cuenta. No necesitas volver a pagar.');
        const cloudActivation = await data.activatePremiumCloudMode();
        if (!cloudActivation.success) {
          console.warn('[SubscriptionPage] Premium restaurado pero sin migración cloud completa:', cloudActivation.message);
        }
        alert(t('subscription.alert.restored'));
        return;
      }

      // Fallback iOS: intentar restaurar desde App Store si aún no hay sincronización por email.
      if (runtimePlatform === 'ios' && appleBillingService.isAvailable()) {
        const purchases = await appleBillingService.restorePurchases();
        const premiumPurchases = purchases.filter((purchase) =>
          Object.values(APPLE_PRODUCTS).includes(purchase.productId as any)
        );

        if (premiumPurchases.length > 0) {
          const latestPurchase = [...premiumPurchases].sort(
            (a, b) => (b.purchaseDateMs || 0) - (a.purchaseDateMs || 0)
          )[0];

          const verifyApplePurchase = httpsCallable(functions, 'verifyApplePurchase');
          await verifyApplePurchase({
            transactionId: latestPurchase.transactionId,
            originalTransactionId: latestPurchase.originalTransactionId || null,
            productId: latestPurchase.productId,
            purchaseDateMs: latestPurchase.purchaseDateMs || null,
            expirationDateMs: latestPurchase.expirationDateMs || null,
          });

          setAlreadyPremiumByEmail(true);
          setSyncMessage('Premium restaurado desde tu historial de App Store.');
          const cloudActivation = await data.activatePremiumCloudMode();
          if (!cloudActivation.success) {
            console.warn('[SubscriptionPage] Premium restaurado desde iOS pero sin migración cloud completa:', cloudActivation.message);
          }
          alert(t('subscription.alert.restored'));
          return;
        }
      }

      alert(t('subscription.alert.notFound'));
    } catch (error) {
      console.error('[SubscriptionPage] Error al restaurar Premium:', error);
      alert(t('subscription.alert.restoreError'));
    } finally {
      setRestoringAccess(false);
    }
  };

  const handleStartFreeTrial = async () => {
    if (!firebaseUser || !firebaseUser.email) {
      const shouldOpenLogin = window.confirm(
        t('subscription.confirm.requireAccountTrial')
      );
      if (shouldOpenLogin) {
        onRequireAccount();
      }
      return;
    }

    setTrialLoading(true);
    try {
      const startTrialFn = httpsCallable(functions, 'startPremiumTrial');
      const result = await startTrialFn({});
      const payload = result.data as any;

      if (payload?.success) {
        const expiryDate = new Date(payload.expiryTime);
        setSyncMessage(t('subscription.trial.activatedUntil', { date: expiryDate.toLocaleDateString() }));
        const cloudActivation = await data.activatePremiumCloudMode();
        if (!cloudActivation.success) {
          console.warn('[SubscriptionPage] Trial activo pero sin migración cloud completa:', cloudActivation.message);
        }
        alert(t('subscription.trial.alertUntil', { date: expiryDate.toLocaleDateString() }));
        onViewChange(View.DASHBOARD);
        return;
      }

      alert(t('subscription.trial.error.generic'));
    } catch (error: any) {
      console.error('[SubscriptionPage] Error al activar prueba gratuita:', error);
      const code = String(error?.code || '');
      if (code.includes('already-exists')) {
        alert(t('subscription.trial.error.alreadyUsed'));
        return;
      }
      if (code.includes('failed-precondition')) {
        alert(error?.message || t('subscription.trial.error.precondition'));
        return;
      }
      alert(t('subscription.trial.error.retry'));
    } finally {
      setTrialLoading(false);
    }
  };

  const monthlyPriceLabel = useMemo(() => {
    if (runtimePlatform === 'android') {
      const monthlyProduct = googlePlayProducts.find(
        (product) => product.productId === GOOGLE_PLAY_PRODUCTS.premium_monthly_sub
      );

      if (monthlyProduct) {
        const amount = monthlyProduct.priceAmountMicros / 1_000_000;
        const localized = formatCurrencyLabel(amount, monthlyProduct.priceCurrencyCode, preferredLocale);
        return localized || monthlyProduct.price || appConfig.premium.monthlyPriceLabel || '2,50€';
      }
    }

    if (runtimePlatform === 'ios') {
      const monthlyProduct = appleProducts.find(
        (product) => product.productId === APPLE_PRODUCTS.premium_monthly_sub
      );

      if (monthlyProduct) {
        const localized = formatCurrencyLabel(monthlyProduct.priceAmount ?? NaN, monthlyProduct.currencyCode, preferredLocale);
        return localized || monthlyProduct.price || appConfig.premium.monthlyPriceLabel || '2,50€';
      }
    }

    const fallback = appConfig.premium.monthlyPriceLabel || '2,50€';
    return localizeAdminPriceLabel(fallback, preferredLocale);
  }, [runtimePlatform, googlePlayProducts, appleProducts, preferredLocale, appConfig.premium.monthlyPriceLabel]);

  const yearlyPriceLabel = useMemo(() => {
    if (runtimePlatform === 'android') {
      const yearlyProduct = googlePlayProducts.find(
        (product) => product.productId === GOOGLE_PLAY_PRODUCTS.premium_yearly_sub
      );

      if (yearlyProduct) {
        const amount = yearlyProduct.priceAmountMicros / 1_000_000;
        const localized = formatCurrencyLabel(amount, yearlyProduct.priceCurrencyCode, preferredLocale);
        return localized || yearlyProduct.price || appConfig.premium.yearlyPriceLabel || '25€';
      }
    }

    if (runtimePlatform === 'ios') {
      const yearlyProduct = appleProducts.find(
        (product) => product.productId === APPLE_PRODUCTS.premium_yearly_sub
      );

      if (yearlyProduct) {
        const localized = formatCurrencyLabel(yearlyProduct.priceAmount ?? NaN, yearlyProduct.currencyCode, preferredLocale);
        return localized || yearlyProduct.price || appConfig.premium.yearlyPriceLabel || '25€';
      }
    }

    const fallback = appConfig.premium.yearlyPriceLabel || '25€';
    return localizeAdminPriceLabel(fallback, preferredLocale);
  }, [runtimePlatform, googlePlayProducts, appleProducts, preferredLocale, appConfig.premium.yearlyPriceLabel]);

  const yearlyMonthlyEquivalent = useMemo(() => {
    if (runtimePlatform === 'android') {
      const yearlyProduct = googlePlayProducts.find(
        (product) => product.productId === GOOGLE_PLAY_PRODUCTS.premium_yearly_sub
      );

      if (yearlyProduct?.priceAmountMicros && yearlyProduct.priceCurrencyCode) {
        const monthlyEquivalent = yearlyProduct.priceAmountMicros / 1_000_000 / 12;
        const localized = formatCurrencyLabel(monthlyEquivalent, yearlyProduct.priceCurrencyCode, preferredLocale);
        if (localized) return localized;
      }
    }

    if (runtimePlatform === 'ios') {
      const yearlyProduct = appleProducts.find(
        (product) => product.productId === APPLE_PRODUCTS.premium_yearly_sub
      );

      if (typeof yearlyProduct?.priceAmount === 'number') {
        const monthlyEquivalent = yearlyProduct.priceAmount / 12;
        const localized = formatCurrencyLabel(monthlyEquivalent, yearlyProduct.currencyCode, preferredLocale);
        if (localized) return localized;
      }
    }

    const fallback = appConfig.premium.yearlyMonthlyEquivalentLabel || '2,08€';
    return localizeAdminPriceLabel(fallback, preferredLocale);
  }, [
    runtimePlatform,
    googlePlayProducts,
    appleProducts,
    preferredLocale,
    appConfig.premium.yearlyMonthlyEquivalentLabel,
  ]);

  return (
    <div className="min-h-[100dvh] bg-gradient-to-b from-slate-50 via-blue-50 to-indigo-50 dark:from-slate-950 dark:via-slate-900 dark:to-slate-950 px-4 py-4">
      <div className="max-w-5xl mx-auto">
        <section className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm p-5 sm:p-7 mb-4">
          <h1 className="text-2xl sm:text-4xl font-extrabold text-slate-900 dark:text-white leading-tight">
            {t('subscription.hero.title')}
          </h1>
          <p className="text-slate-600 dark:text-slate-300 mt-2 sm:text-lg">
            {t('subscription.hero.description')}
          </p>

          <div className="mt-4 flex flex-wrap gap-2">
            <span className="px-3 py-1 text-xs rounded-full bg-blue-100 text-blue-800 font-semibold">
              {runtimePlatform === 'ios'
                ? 'Apple Pay'
                : runtimePlatform === 'android'
                  ? 'Google Billing'
                  : t('subscription.hero.badge.stripe')}
            </span>
            <span className="px-3 py-1 text-xs rounded-full bg-emerald-100 text-emerald-800 font-semibold">
              {t('subscription.hero.badge.instant')}
            </span>
            <span className="px-3 py-1 text-xs rounded-full bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 font-semibold">
              {t('subscription.hero.badge.cancelAnytime')}
            </span>
          </div>

          <div className="mt-4 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 p-3 sm:p-4">
            <p className="text-sm text-slate-700 dark:text-slate-200">
              {t('subscription.restore.description')}
            </p>
            <div className="mt-3 flex flex-wrap gap-2">
              <button
                onClick={handleRecoverPremiumAccess}
                disabled={loading || restoringAccess}
                className="inline-flex items-center justify-center rounded-lg bg-slate-900 dark:bg-slate-100 hover:bg-slate-800 dark:hover:bg-slate-200 text-white dark:text-slate-900 text-sm font-semibold px-4 py-2 disabled:opacity-60"
              >
                {restoringAccess
                  ? t('subscription.restore.loading')
                  : firebaseUser?.email
                    ? t('subscription.restore.button')
                    : t('subscription.restore.loginButton')}
              </button>
              {firebaseUser?.email && (
                <button
                  onClick={() => data.logout()}
                  className="inline-flex items-center justify-center rounded-lg border border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-900 hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-200 text-sm font-semibold px-4 py-2"
                >
                  {t('header.logout')}
                </button>
              )}
            </div>
          </div>
        </section>

        {(isPremium || alreadyPremiumByEmail) && (
          <section className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 mb-4">
            <p className="text-emerald-800 font-semibold">
              {t('subscription.active.title')}
            </p>
            <p className="text-emerald-700 text-sm mt-1">
              {syncMessage || `Estado actual: ${subscriptionStatus || 'active'}`}
            </p>
          </section>
        )}

        <section className="bg-gradient-to-b from-indigo-600 to-blue-700 rounded-2xl text-white p-5 sm:p-6 shadow-lg mb-4">
          <div className="flex items-center gap-2 mb-4">
            <CheckCircleIcon className="w-6 h-6 text-emerald-300" />
            <h3 className="text-lg font-bold">{t('subscription.plan.title')}</h3>
          </div>
          {!purchaseEnabledOnPlatform && (
            <p className="mb-3 text-sm bg-red-500/40 border border-red-300/60 rounded-md px-3 py-2">
              {t('subscription.plan.disabled')}
            </p>
          )}
          <button
            onClick={handleStartFreeTrial}
            disabled={!canStartTrial}
            className="w-full mb-3 text-left bg-emerald-500 hover:bg-emerald-400 rounded-xl p-4 transition disabled:opacity-60"
          >
            <p className="font-semibold flex items-center gap-2"><span>🎁</span><span>{t('subscription.trial.title')}</span></p>
            <p className="text-sm mt-1 text-emerald-50">
              {t('subscription.trial.description')}
            </p>
          </button>
          <div className="grid sm:grid-cols-2 gap-3">
            <button
              onClick={() => handleSubscription('monthly')}
              disabled={!canPurchase || (nativeBillingRequiresReady && !billingReady)}
              className="w-full text-left bg-white/10 hover:bg-white/20 rounded-xl p-4 transition disabled:opacity-60"
            >
              <p className="font-semibold flex items-center gap-2"><span>📅</span><span>{t('subscription.plan.monthly')}</span></p>
              <p className="text-3xl font-extrabold mt-1">{monthlyPriceLabel} <span className="text-sm font-medium">{t('subscription.plan.perMonth')}</span></p>
              <p className="text-xs text-blue-100 mt-1">{t('subscription.plan.monthlyHint')}</p>
            </button>

            <button
              onClick={() => handleSubscription('yearly')}
              disabled={!canPurchase || (nativeBillingRequiresReady && !billingReady)}
              className="w-full text-left bg-yellow-300 text-slate-900 hover:bg-yellow-200 rounded-xl p-4 transition disabled:opacity-60"
            >
              <p className="font-semibold flex items-center gap-2"><span>⭐</span><span>{t('subscription.plan.yearly')}</span></p>
              <p className="text-3xl font-extrabold mt-1">{yearlyPriceLabel} <span className="text-sm font-medium">{t('subscription.plan.perYear')}</span></p>
              <p className="text-xs mt-1">{t('subscription.plan.yearlyHint', { price: yearlyMonthlyEquivalent })}</p>
            </button>
          </div>

          <p className="text-xs text-blue-100 mt-4">
            {t('subscription.plan.emailSyncHint')}
          </p>
          {nativeBillingRequiresReady && !billingReady && (
            <p className="text-xs text-amber-200 mt-2">
              {t('subscription.plan.loadingNative')}
            </p>
          )}
          {runtimePlatform === 'ios' && billingError && (
            <p className="text-xs text-red-200 mt-2">
              {billingError}
            </p>
          )}
        </section>

        <section className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-700 p-5 sm:p-6 shadow-sm mb-4">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-3">{t('subscription.features.title')}</h2>
          <div className="grid sm:grid-cols-2 gap-3">
            {premiumFeatures.map((feature) => (
              <div key={feature.text} className="flex items-start gap-2 p-3 rounded-lg bg-slate-50 dark:bg-slate-800 border border-slate-100 dark:border-slate-700">
                <span className="text-lg leading-none mt-0.5">{feature.icon}</span>
                <span className="text-sm text-slate-700 dark:text-slate-200">{feature.text}</span>
              </div>
            ))}
          </div>
        </section>

        <section className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-4 mb-4">
          <h3 className="font-semibold text-slate-900 dark:text-white mb-2">{t('subscription.benefits.title')}</h3>
          <p className="text-sm text-slate-700 dark:text-slate-300">
            {t('subscription.benefits.description')}
          </p>
        </section>
      </div>
    </div>
  );
};

export default SubscriptionPage;
