import React, { useState, useEffect } from 'react';
import { Task, Periodicity, NewTaskPayload, User, TaskStatus, ReminderUnit } from '../types';
import { PERIODICITY_OPTIONS } from '../constants';
import { PlusIcon, CheckIcon, Cog6ToothIcon, EnvelopeIcon } from './Icons';
import Modal from './Modal';
import { useSubscription } from '../hooks/useSubscription';
import PeriodicTaskDayManager from './PeriodicTaskDayManager';
import { notificationService } from '../services/notificationService';
import { useI18n } from '../i18n/I18nProvider';

interface TaskFormProps {
  onSave: (task: NewTaskPayload | Task) => Promise<void>;
  onCancel: () => void;
  task: Task | null;
  homeId: string;
  members: User[];
  currentUser: User;
  selectedDate?: Date;
  onUpdateDayAssignment?: (dayIndex: number, assignedTo: string | null, specificDate: Date) => Promise<void>;
  onUpdateDayStatus?: (dayIndex: number, status: TaskStatus, specificDate: Date) => Promise<void>;
  getPeriodicTaskDayInfo?: (task: Task, dayIndex: number) => { status: TaskStatus; assignedTo: string | null };
}

const isSingleEmoji = (str: string) => {
  // Regex para un solo emoji
  return /^\p{Emoji}$/u.test(str);
};

const parseDateInput = (value: string): Date => {
  const [year, month, day] = value.split('-').map(Number);
  return new Date(year, (month || 1) - 1, day || 1);
};

const normalizeDay = (date: Date): Date => {
  const normalized = new Date(date);
  normalized.setHours(0, 0, 0, 0);
  return normalized;
};

const formatDateForInputLocal = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const TaskForm: React.FC<TaskFormProps> = ({ onSave, onCancel, task, homeId, members, currentUser, selectedDate, onUpdateDayAssignment, onUpdateDayStatus, getPeriodicTaskDayInfo }) => {
  const { t } = useI18n();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [emoji, setEmoji] = useState<string>('🧹');
  const [points, setPoints] = useState(0);
  const [dueDate, setDueDate] = useState(selectedDate || new Date());
  const [endDate, setEndDate] = useState<Date | null>(null);
  const [periodicity, setPeriodicity] = useState<Periodicity>(Periodicity.NONE);
  const [customDays, setCustomDays] = useState<number>(7);
  const [assignedTo, setAssignedTo] = useState<string | undefined>(undefined);
  const [reminderEnabled, setReminderEnabled] = useState(false);
  const [reminderAmount, setReminderAmount] = useState(30);
  const [reminderUnit, setReminderUnit] = useState<ReminderUnit>('minutes');
  const [loading, setLoading] = useState(false);
  const [modalVisible, setModalVisible] = useState(false);
  const [modalMessage, setModalMessage] = useState<{ message: string; type: 'error' | 'success' } | null>(null);
  const [validationErrors, setValidationErrors] = useState<{
    title?: boolean;
    emoji?: boolean;
    dueDate?: boolean;
    endDate?: boolean;
  }>({});
  const [validationMessage, setValidationMessage] = useState<string>('');
  
  // Usar el hook de suscripción para verificar límites
  const { isPremium } = useSubscription(currentUser, [], null, []);

  useEffect(() => {
    if (task) {
      setTitle(task.title);
      setDescription(task.description);
      setEmoji(task.emoji);
      setPoints(task.points);
      setDueDate(new Date(task.dueDate));
      setEndDate(task.endDate ? new Date(task.endDate) : null);
      setPeriodicity(task.periodicity);
      setCustomDays(task.customDays ?? 7);
      setAssignedTo(task.assignedTo ?? undefined);
      if (task.reminder?.enabled) {
        setReminderEnabled(true);
        setReminderAmount(Math.max(1, Math.floor(task.reminder.amount || 1)));
        setReminderUnit(task.reminder.unit || 'minutes');
      } else {
        setReminderEnabled(false);
        setReminderAmount(30);
        setReminderUnit('minutes');
      }
    } else {
      // Si es una nueva tarea, usar la fecha seleccionada del calendario
      setDueDate(selectedDate || new Date());
      setEndDate(null);
      setReminderEnabled(false);
      setReminderAmount(30);
      setReminderUnit('minutes');
    }
  }, [task, selectedDate]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Resetear errores anteriores
    setValidationErrors({});
    setValidationMessage('');
    
    // Validar campos obligatorios
    const errors: typeof validationErrors = {};
    const missingFields: string[] = [];
    
    if (!title.trim()) {
      errors.title = true;
      missingFields.push(t('taskForm.field.title'));
    }
    
    if (!emoji.trim()) {
      errors.emoji = true;
      missingFields.push(t('taskForm.field.icon'));
    }
    
    if (!dueDate) {
      errors.dueDate = true;
      missingFields.push(t('taskForm.field.dueDate'));
    }
    
    // Validar fecha fin para tareas periódicas
    if (periodicity !== Periodicity.NONE && !endDate && !task) {
      errors.endDate = true;
      missingFields.push(t('taskForm.field.repeatUntil'));
    }

    if (reminderEnabled && (!Number.isFinite(reminderAmount) || reminderAmount <= 0)) {
      setModalMessage({
        message: t('taskForm.validation.reminderAmount'),
        type: 'error'
      });
      setModalVisible(true);
      return;
    }
    
    // Si hay errores, mostrarlos y no continuar
    if (Object.keys(errors).length > 0) {
      setValidationErrors(errors);
      setValidationMessage(t('taskForm.validation.required', { fields: missingFields.join(', ') }));
      setModalMessage({ 
        message: t('taskForm.validation.completeFields', { fields: missingFields.join(', ') }), 
        type: 'error' 
      });
      setModalVisible(true);
      return;
    }
    
    const isEditingPeriodicTask = !!task && task.periodicity !== Periodicity.NONE;
    if (isEditingPeriodicTask) {
      const reminderChanged =
        !!task?.reminder?.enabled !== reminderEnabled ||
        Number(task?.reminder?.amount || 0) !== (reminderEnabled ? Math.max(1, Math.floor(reminderAmount)) : 0) ||
        String(task?.reminder?.unit || 'minutes') !== String(reminderEnabled ? reminderUnit : 'minutes');
      const affectsAllOccurrences =
        title.trim() !== String(task?.title || '').trim() ||
        description.trim() !== String(task?.description || '').trim() ||
        emoji !== String(task?.emoji || '') ||
        Number(points) !== Number(task?.points || 0) ||
        (assignedTo || null) !== (task?.assignedTo || null) ||
        reminderChanged;

      if (affectsAllOccurrences) {
        const accepted = window.confirm(
          t('taskForm.confirm.applyCurrentOnly')
        );
        if (!accepted) return;
      }
    }

    setLoading(true);

    const normalizedReminderAmount = Math.max(1, Math.floor(reminderAmount));
    
    // Crear el objeto base de datos de la tarea
    let taskData: any = {
      title,
      description,
      emoji,
      points,
      dueDate: dueDate.toISOString(),
      homeId,
      assignedTo: assignedTo || null, // Aseguramos que se guarde como null si no está asignado
      reminder: reminderEnabled
        ? {
            enabled: true,
            amount: normalizedReminderAmount,
            unit: reminderUnit,
          }
        : null,
    };
    
    // Si es una tarea nueva, incluir los campos de periodicidad
    if (!task) {
      taskData = {
        ...taskData,
        periodicity,
        endDate: periodicity !== Periodicity.NONE && endDate ? endDate.toISOString() : null,
        customDays: periodicity === Periodicity.CUSTOM_DAYS ? customDays : null,
      };
    } else {
      // Si es una tarea existente, mantener los valores originales de periodicidad
      taskData = {
        ...taskData,
        periodicity: task.periodicity,
        dueDate: task.periodicity !== Periodicity.NONE ? task.dueDate : dueDate.toISOString(),
        endDate: task.endDate ? task.endDate : null,
        customDays: task.customDays,
      };
    }
    try {
      if (task && 'id' in task) {
        // Filtrar campos undefined para evitar errores de Firebase
        const updatedTask = { ...task, ...taskData };
        // Eliminar campos undefined o null que pueden causar errores
        Object.keys(updatedTask).forEach(key => {
          if (updatedTask[key] === undefined) {
            delete updatedTask[key];
          }
        });
        await onSave(updatedTask);
      } else {
        // Track analytics for new task creation
        const isPeriodicTask = periodicity !== Periodicity.NONE;
        await notificationService.recordPremiumFeatureAttempt(
          currentUser.id,
          isPeriodicTask ? 'periodic_task_creation' : 'task_creation',
          {
            periodicity,
            hasEndDate: !!endDate,
            points,
            homeId
          }
        );
        
        await onSave(taskData as NewTaskPayload);
      }
      setModalMessage({ message: t('taskForm.savedSuccess'), type: 'success' });
    } catch (error) {
      console.log(error);
      setModalMessage({ message: t('taskForm.savedError'), type: 'error' });
    } finally {
      setLoading(false);
      setModalVisible(true);
    }
  };

  const handleEmojiChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    
    // Si el valor está vacío, permitirlo
    if (value === '') {
      setEmoji(value);
      return;
    }
    
    // Si es un emoji válido (longitud <= 2 y pasa la prueba de emoji único)
    if (value.length <= 2 && isSingleEmoji(value)) {
      setEmoji(value);
      return;
    }
    
    // Si no es válido, mostrar error solo si el usuario está escribiendo (no al hacer click)
    // Esto evita errores al cambiar de un emoji a otro
    const lastChar = value.slice(-1);
    if (isSingleEmoji(lastChar)) {
      // Si el último carácter es un emoji válido, usar solo ese
      setEmoji(lastChar);
    } else {
      setModalMessage({ message: t('taskForm.validation.validEmoji'), type: 'error' });
      setModalVisible(true);
    }
  };

  const formattedDateForInput = (date: Date) => formatDateForInputLocal(date);

  return (
    <>
      <form onSubmit={handleSubmit} className="p-4 sm:p-5 md:p-6 space-y-5 bg-white dark:bg-slate-800 rounded-xl shadow-lg w-full border border-slate-200 dark:border-slate-700 overflow-x-hidden">
        
        <div className="text-center mb-6">
          <div className="flex items-center justify-center gap-3 mb-4">
            <div className="inline-flex items-center justify-center w-8 h-8 bg-gradient-to-r from-blue-500 to-purple-600 rounded-full shadow-md">
              <PlusIcon className="w-5 h-5 text-white" />
            </div>
            <h2 className="text-2xl font-bold text-primary-600 dark:text-primary-400">
              {task ? t('taskForm.title.edit') : t('taskForm.title.create')}
            </h2>
          </div>
        </div>

        {/* Mensaje de validación */}
        {validationMessage && (
          <div className="bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 p-4 rounded">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <svg className="h-5 w-5 text-red-500" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
              </div>
              <div className="ml-3">
                <p className="text-sm font-medium text-red-800 dark:text-red-200">{validationMessage}</p>
              </div>
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          
          <div className="md:col-span-2 bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-200 dark:border-blue-800">
            <div className="flex items-center gap-2 mb-4">
              <div className="w-6 h-6 bg-blue-100 dark:bg-blue-900 rounded-lg flex items-center justify-center">
                <CheckIcon className="w-4 h-4 text-blue-600 dark:text-blue-400" />
              </div>
              <h3 className="text-lg font-semibold text-blue-700 dark:text-blue-300">{t('taskForm.section.basic')}</h3>
            </div>
            
            <div className="space-y-4">
              <div>
                <label htmlFor="title" className={`block text-sm font-medium mb-1 ${validationErrors.title ? 'text-red-600 dark:text-red-400' : 'text-slate-700 dark:text-slate-300'}`}>
                  {t('taskForm.field.title')} {validationErrors.title && <span className="text-red-500">*</span>}
                </label>
                <div className="relative">
                  <input 
                    type="text" 
                    id="title" 
                    value={title} 
                    onChange={(e) => {
                      setTitle(e.target.value);
                      if (validationErrors.title && e.target.value.trim()) {
                        setValidationErrors(prev => ({ ...prev, title: false }));
                        setValidationMessage('');
                      }
                    }} 
                    maxLength={16}
                    required 
                    className={`mt-1 block w-full px-3 py-2 rounded-lg shadow-sm focus:ring-primary-500 text-base font-medium ${
                      validationErrors.title 
                        ? 'border-2 border-red-500 dark:border-red-400 focus:border-red-500' 
                        : 'border-slate-300 dark:border-slate-600 focus:border-primary-500'
                    } dark:bg-slate-700`} 
                    placeholder={t('taskForm.placeholder.title')}
                  />
                  <div className="absolute right-2 top-2 text-xs text-slate-500 dark:text-slate-400">
                    {title.length}/16
                  </div>
                </div>
              </div>

              <div>
                <label htmlFor="description" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  {t('taskForm.field.descriptionOptional')}
                </label>
                <div className="relative">
                  <textarea 
                    id="description" 
                    value={description} 
                    onChange={(e) => setDescription(e.target.value)} 
                    maxLength={200}
                    rows={3} 
                    className="mt-1 block w-full px-3 py-2 rounded-lg border-slate-300 dark:border-slate-600 dark:bg-slate-700 shadow-sm focus:border-primary-500 focus:ring-primary-500"
                    placeholder={t('taskForm.placeholder.description')}
                  />
                  <div className="absolute right-2 bottom-2 text-xs text-slate-500 dark:text-slate-400">
                    {description.length}/200
                  </div>
                </div>
              </div>
            </div>
          </div>

      <div className="md:col-span-2 bg-purple-50 dark:bg-purple-900/20 p-4 rounded-lg border border-purple-200 dark:border-purple-800">
            {/* Header */}
            <div className="flex items-center gap-2 mb-4">
              <div className="w-5 h-5 bg-purple-100 dark:bg-purple-900 rounded-md flex items-center justify-center">
                <Cog6ToothIcon className="w-3.5 h-3.5 text-purple-600 dark:text-purple-400" />
              </div>

              <h3 className="text-lg font-semibold text-purple-700 dark:text-purple-300">
                {t('taskForm.section.config')}
              </h3>
            </div>

            {/* CONTROLES */}
          <div className="flex flex-row gap-6 items-end">

              {/* ICONO */}
              <div className="flex flex-col md:w-auto">
                <label
                  htmlFor="emoji"
                  className={`block text-sm font-medium mb-1 ${
                    validationErrors.emoji
                      ? 'text-red-600 dark:text-red-400'
                      : 'text-slate-700 dark:text-slate-300'
                  }`}
                >
                  {t('taskForm.field.icon')} {validationErrors.emoji && <span className="text-red-500">*</span>}
                </label>

                <input
                  type="text"
                  value={emoji}
                  onChange={(e) => {
                    handleEmojiChange(e);
                    if (validationErrors.emoji && e.target.value.trim()) {
                      setValidationErrors(prev => ({ ...prev, emoji: false }));
                      setValidationMessage('');
                    }
                  }}
                  className={`text-xl w-12 h-12 text-center rounded-lg transition-all ${
                    validationErrors.emoji
                      ? 'border-2 border-red-500 dark:border-red-400 focus:border-red-500 focus:ring-2 focus:ring-red-500'
                      : 'border-2 border-slate-300 dark:border-slate-600 focus:border-primary-500 focus:ring-2 focus:ring-primary-500 hover:border-primary-400'
                  } bg-slate-50 dark:bg-slate-700`}
                  placeholder="😊"
                />
              </div>

              {/* PUNTOS */}
              <div className="flex flex-col md:w-auto">
                <label
                  htmlFor="points"
                  className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1"
                >
                  {t('taskForm.field.points')}
                </label>

                <div className="flex items-center gap-3">
                  <input
                    type="number"
                    id="points"
                    min={0}
                    max={100}
                    step={1}
                    value={points}
                    onChange={(e) => {
                      const value = Number(e.target.value);
                      if (value >= 0 && value <= 100) {
                        setPoints(value);
                      }
                    }}
                    onFocus={(e) => e.target.select()}
                    className="w-20 h-12 px-3 rounded-lg border-2 border-slate-300 dark:border-slate-600 bg-slate-50 dark:bg-slate-700 focus:border-primary-500 focus:ring-2 focus:ring-primary-500 text-center font-semibold text-lg"
                  />

                  <span className="text-xs text-slate-500 dark:text-slate-400">
                    0–100
                  </span>
                </div>
              </div>

            </div>
          </div>

          <div className="md:col-span-2 bg-green-50 dark:bg-green-900/20 p-4 rounded-lg border border-green-200 dark:border-green-800 overflow-hidden">
            <div className="flex items-center gap-2 mb-4">
              <div className="w-6 h-6 bg-green-100 dark:bg-green-900 rounded-lg flex items-center justify-center">
                <CheckIcon className="w-4 h-4 text-green-600 dark:text-green-400" />
              </div>
              <h3 className="text-lg font-semibold text-green-700 dark:text-green-300">{t('taskForm.section.dates')}</h3>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 relative">
              <div className="min-w-0">
                <label htmlFor="dueDate" className={`block text-sm font-medium mb-1 ${validationErrors.dueDate ? 'text-red-600 dark:text-red-400' : 'text-slate-700 dark:text-slate-300'}`}>
                  {t('taskForm.field.dueDate')} {validationErrors.dueDate && <span className="text-red-500">*</span>}
                </label>
                <input 
                    type="date" 
                    id="dueDate" 
                    value={formattedDateForInput(dueDate)} 
                    min={periodicity !== Periodicity.NONE ? new Date().toISOString().slice(0, 10) : undefined}
                  onChange={(e) => {
                    const newDate = parseDateInput(e.target.value);
                    if (periodicity !== Periodicity.NONE) {
                      const today = normalizeDay(new Date());
                      if (normalizeDay(newDate) < today) {
                        setModalMessage({
                          message: t('taskForm.validation.periodicFromToday'),
                          type: 'error'
                        });
                        setModalVisible(true);
                        return;
                      }
                    }
                    setDueDate(newDate);
                    if (validationErrors.dueDate) {
                      setValidationErrors(prev => ({ ...prev, dueDate: false }));
                      setValidationMessage('');
                    }
                  }} 
                  required 
                  className={`task-date-input mt-1 block w-full max-w-full px-3 py-2 text-base rounded-lg shadow-sm focus:ring-primary-500 ${
                    validationErrors.dueDate
                      ? 'border-2 border-red-500 dark:border-red-400 focus:border-red-500'
                      : 'border-slate-300 dark:border-slate-600 focus:border-primary-500'
                  } dark:bg-slate-700`} 
                />
                {periodicity !== Periodicity.NONE && (
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                    {t('taskForm.validation.periodicFromToday')}
                  </p>
                )}
              </div>

              <div className="min-w-0">
                <label htmlFor="periodicity" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  {t('taskForm.field.periodicity')}
                </label>
                <select 
                  id="periodicity" 
                  value={periodicity} 
                  onChange={(e) => setPeriodicity(e.target.value as Periodicity)} 
                  className="mt-1 block w-full min-w-0 px-3 py-2 rounded-lg border-slate-300 dark:border-slate-600 dark:bg-slate-700 shadow-sm focus:border-primary-500 focus:ring-primary-500"
                  disabled={task !== null}
                >
                  {PERIODICITY_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
                </select>
                {task && (
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                    {t('taskForm.validation.periodicityFixed')}
                  </p>
                )}
              </div>

              {periodicity !== Periodicity.NONE && (
                <div className="md:col-span-2 min-w-0">
                  <label htmlFor="endDate" className={`block text-sm font-medium mb-1 ${validationErrors.endDate ? 'text-red-600 dark:text-red-400' : 'text-slate-700 dark:text-slate-300'}`}>
                    {t('taskForm.field.repeatUntil')} {validationErrors.endDate && <span className="text-red-500">*</span>}
                  </label>
                  <input 
                    type="date" 
                    id="endDate" 
                    value={endDate ? formatDateForInputLocal(endDate) : ''} 
                    max={formatDateForInputLocal(new Date(new Date().setDate(new Date().getDate() + 365)))}
                    onChange={(e) => {
                      if (e.target.value) {
                        const selectedEndDate = parseDateInput(e.target.value);
                        const maxDate = normalizeDay(new Date());
                        maxDate.setDate(maxDate.getDate() + 365);
                        
                        if (normalizeDay(selectedEndDate) > maxDate) {
                          setModalMessage({
                            message: t('taskForm.validation.maxOneYear'),
                            type: 'error'
                          });
                          setModalVisible(true);
                          return;
                        }
                        
                        const dueDateValue = formattedDateForInput(dueDate);
                        if (e.target.value < dueDateValue) {
                          setModalMessage({
                            message: t('taskForm.validation.afterStart'),
                            type: 'error'
                          });
                          setModalVisible(true);
                          return;
                        }
                        
                        setEndDate(selectedEndDate);
                        if (validationErrors.endDate) {
                          setValidationErrors(prev => ({ ...prev, endDate: false }));
                          setValidationMessage('');
                        }
                      } else {
                        setEndDate(null);
                      }
                    }} 
                    className={`task-date-input mt-1 block w-full max-w-full px-3 py-2 text-base rounded-lg shadow-sm focus:ring-primary-500 ${
                      validationErrors.endDate
                        ? 'border-2 border-red-500 dark:border-red-400 focus:border-red-500'
                        : 'border-slate-300 dark:border-slate-600 focus:border-primary-500'
                    } dark:bg-slate-700`} 
                    disabled={task !== null}
                  />
                  <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                    {task ? t('taskForm.validation.repeatUntilFixed') : t('taskForm.hint.repeatUntilOptional')}
                  </p>
                </div>
              )}

              {periodicity === Periodicity.CUSTOM_DAYS && (
                <div className="md:col-span-2">
                  <label htmlFor="customDays" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    {t('taskForm.field.everyDays')}
                  </label>
                  <input 
                    type="number" 
                    id="customDays" 
                    min="1" 
                    max="365" 
                    value={customDays} 
                    onChange={(e) => setCustomDays(Math.max(1, parseInt(e.target.value) || 1))} 
                    className="mt-1 block w-full px-3 py-2 rounded-lg border-slate-300 dark:border-slate-600 dark:bg-slate-700 shadow-sm focus:border-primary-500 focus:ring-primary-500" 
                    disabled={task !== null}
                  />
                  {task && (
                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                      {t('taskForm.validation.customDaysFixed')}
                    </p>
                  )}
                </div>
              )}

              <div className="md:col-span-2 min-w-0 overflow-hidden">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  {t('taskForm.field.localReminder')}
                </label>
                <div className="flex flex-col sm:flex-row sm:items-center gap-3 p-3 rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50">
                  <label className="inline-flex items-center gap-2 text-sm text-slate-700 dark:text-slate-300">
                    <input
                      type="checkbox"
                      checked={reminderEnabled}
                      onChange={(e) => setReminderEnabled(e.target.checked)}
                      className="h-4 w-4 rounded border-slate-300 text-primary-600 focus:ring-primary-500"
                    />
                    {t('taskForm.field.enableReminder')}
                  </label>

                  {reminderEnabled && (
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-sm text-slate-600 dark:text-slate-300">{t('taskForm.field.remind')}</span>
                      <input
                        type="number"
                        min={1}
                        step={1}
                        value={reminderAmount}
                        onChange={(e) => setReminderAmount(Math.max(1, Number(e.target.value) || 1))}
                        className="w-20 px-2 py-1.5 rounded-md border border-slate-300 dark:border-slate-600 dark:bg-slate-700 text-sm"
                      />
                      <select
                        value={reminderUnit}
                        onChange={(e) => setReminderUnit(e.target.value as ReminderUnit)}
                        className="px-2 py-1.5 rounded-md border border-slate-300 dark:border-slate-600 dark:bg-slate-700 text-sm"
                      >
                        <option value="minutes">{t('taskForm.unit.minutes')}</option>
                        <option value="hours">{t('taskForm.unit.hours')}</option>
                        <option value="days">{t('taskForm.unit.days')}</option>
                      </select>
                      <span className="text-sm text-slate-600 dark:text-slate-300">{t('taskForm.field.before')}</span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* Asignación */}
          {task && task.periodicity !== Periodicity.NONE && onUpdateDayAssignment && onUpdateDayStatus && getPeriodicTaskDayInfo ? (
            <div className="md:col-span-2 bg-teal-50 dark:bg-teal-900/20 p-4 rounded-lg border border-teal-200 dark:border-teal-800">
              <div className="flex items-center gap-2 mb-4">
                <div className="w-6 h-6 bg-teal-100 dark:bg-teal-900 rounded-lg flex items-center justify-center">
                  <EnvelopeIcon className="w-4 h-4 text-teal-600 dark:text-teal-400" />
                </div>
                <h3 className="text-lg font-semibold text-teal-700 dark:text-teal-300">{t('taskForm.section.dailyManagement')}</h3>
              </div>
              <PeriodicTaskDayManager
                task={task}
                users={members}
                onUpdateDayAssignment={(dayIndex, assignedTo, specificDate) => 
                  onUpdateDayAssignment(dayIndex, assignedTo, specificDate)
                }
                onUpdateDayStatus={(dayIndex, status, specificDate) => 
                  onUpdateDayStatus(dayIndex, status, specificDate)
                }
                getPeriodicTaskDayInfo={getPeriodicTaskDayInfo}
              />
            </div>
          ) : (
            <div className="md:col-span-2 bg-emerald-50 dark:bg-emerald-900/20 p-4 rounded-lg border border-emerald-200 dark:border-emerald-800">
              <div className="flex items-center gap-2 mb-4">
                <div className="w-6 h-6 bg-emerald-100 dark:bg-emerald-900 rounded-lg flex items-center justify-center">
                  <EnvelopeIcon className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
                </div>
                <h3 className="text-lg font-semibold text-emerald-700 dark:text-emerald-300">{t('taskForm.section.assignment')}</h3>
              </div>
              <label htmlFor="assignedTo" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                {t('taskForm.field.assignTo')}
              </label>
              <select 
                id="assignedTo" 
                value={assignedTo || ''} 
                onChange={(e) => setAssignedTo(e.target.value || undefined)} 
                className="mt-1 block w-full px-3 py-2 rounded-lg border-slate-300 dark:border-slate-600 dark:bg-slate-700 shadow-sm focus:border-primary-500 focus:ring-primary-500"
              >
                <option value="">{t('taskForm.field.unassigned')}</option>
                {members.map(member => <option key={member.id} value={member.id}>{member.name}</option>)}
              </select>
            </div>
          )}
        </div>

        {/* Botones de Acción */}
        <div className="mt-2 pt-3 border-t border-slate-200 dark:border-slate-700 flex justify-end gap-3">
          <button 
            type="button" 
            onClick={onCancel} 
            className="px-4 py-2 bg-slate-200 dark:bg-slate-600 hover:bg-slate-300 dark:hover:bg-slate-500 text-slate-800 dark:text-slate-100 font-medium rounded-lg transition-colors duration-200"
          >
            {t('common.close')}
          </button>
          <button 
            type="submit" 
            disabled={loading || !isSingleEmoji(emoji)} 
            className="px-4 py-2 bg-primary-600 hover:bg-primary-700 text-white font-medium rounded-lg flex items-center gap-2 disabled:bg-primary-300 transition-colors duration-200"
          >
            <PlusIcon className="w-5 h-5" />
            {loading ? t('taskForm.saving') : (task ? t('taskForm.saveChanges') : t('taskForm.createTask'))}
          </button>
        </div>
      </form>
      
      {modalVisible && modalMessage && (
        <Modal isOpen={modalVisible} onClose={() => setModalVisible(false)}>
          <div
            className={`p-4 rounded-md ${
              modalMessage.type === 'success'
                ? 'bg-green-100 dark:bg-green-900/50 text-green-700 dark:text-green-200'
                : 'bg-red-100 dark:bg-red-900/50 text-red-700 dark:text-red-200'
            }`}
          >
            <p>{modalMessage.message}</p>
            <button
              onClick={() => setModalVisible(false)}
              className="mt-4 px-4 py-2 bg-primary-600 text-white rounded-md"
            >
              {t('common.close')}
            </button>
          </div>
        </Modal>
      )}
    </>
  );
};

export default TaskForm;
