import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { User, Task, Home, Stats, NewTaskPayload, HomeInvitation, TaskStatus, Periodicity, Reward, RewardClaim, NewRewardPayload, RewardStatus, JoinHomeByInviteOptions } from '../types';
import { AuthStatus } from '../types';
import { useLocalStorage } from './useLocalStorage';
import { dataServiceRouter } from '../services/dataServiceRouter.ts';
import { Notification } from '../models/notification';
import { notificationService } from '../services/notificationService';
import { onAuthStateChanged } from 'firebase/auth';
import { auth } from '../services/firebase';
import { taskReminderService } from '../services/taskReminderService.ts';

// Usar dataServiceRouter en lugar de firebaseDataService directamente
// El router detectará automáticamente si usar Local o Firebase
export const useData = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [homes, setHomes] = useState<Home[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [invitations, setInvitations] = useState<HomeInvitation[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [rewardClaims, setRewardClaims] = useState<RewardClaim[]>([]);
  const [isLocalMode, setIsLocalMode] = useState(true); // Track si estamos en modo local
  
  const [currentHomeId, setCurrentHomeId] = useLocalStorage<string | null>('houseZen-current-home', null);
  const currentHomeIdRef = useRef<string | null>(currentHomeId);
  const [authStatus, setAuthStatus] = useState<AuthStatus>('loading');
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  useEffect(() => {
    currentHomeIdRef.current = currentHomeId;
  }, [currentHomeId]);
  
  // Auth state listener - Ahora usa el servicio del router
  useEffect(() => {
    setAuthStatus('loading');

    let unsubscribeAuth: (() => void) | null = null;

    const subscribeToCurrentService = () => {
      if (unsubscribeAuth) {
        try { unsubscribeAuth(); } catch (e) { /* ignore */ }
        unsubscribeAuth = null;
      }

      const dataService = dataServiceRouter.getService();
      unsubscribeAuth = dataService.onAuthStateChange((user) => {
        // Actualizar el router con el usuario actual
        dataServiceRouter.updateUser(user);
        setIsLocalMode(dataServiceRouter.isUsingLocalService());

        if (user) {
          setCurrentUser(user);
          setAuthStatus('logged-in');
        } else {
          setCurrentUser(null);
          setAuthStatus('logged-out');
          setCurrentHomeId(null);
        }
      });
    };

    // Suscribir inicialmente
    subscribeToCurrentService();

    // Re-suscribir cuando el router cambia de servicio
    const unsubscribeRouter = dataServiceRouter.onChange(() => {
      subscribeToCurrentService();
    });

    return () => {
      if (unsubscribeAuth) try { unsubscribeAuth(); } catch (e) {}
      unsubscribeRouter();
    };
  }, []);

  // Escuchar auth de Firebase incluso cuando estamos en modo local, para poder
  // activar/desactivar cloud según premium o membresías compartidas.
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, () => {
      void dataServiceRouter.syncWithFirebaseAuthContext();
    });
    return () => unsubscribe();
  }, []);
  
  // Google login function ya está definido más abajo

  // Real-time data listeners
  useEffect(() => {
    if (!currentUser) {
        setHomes([]);
        setTasks([]);
        setInvitations([]);
        setUsers([]);
        setNotifications([]);
        void taskReminderService.syncTaskReminders([]);
        return;
    };
    
    // Suscripción en tiempo real a las notificaciones
    let notificationUnsubscribe: (() => void) | null = null;
    
    // Obtener el servicio de datos al inicio del effect to avoid TDZ
    const dataService = dataServiceRouter.getService();

    // Usar el método de suscripción del servicio de datos si está disponible
    if (dataService.subscribeToNotifications) {
      notificationUnsubscribe = dataService.subscribeToNotifications(
        currentUser.id,
        (updatedNotifications) => {
          setNotifications(updatedNotifications);
        }
      );
    } 
    // Si no está disponible en el servicio de datos, intentar con el servicio de notificaciones directamente
    else if (notificationService.subscribeToUserNotifications) {
      notificationUnsubscribe = notificationService.subscribeToUserNotifications(
        currentUser.id,
        (updatedNotifications) => {
          setNotifications(updatedNotifications);
        }
      );
    }
    // Fallback a polling si no hay suscripción en tiempo real disponible
    else if (dataService.getNotifications) {
      // Cargar notificaciones iniciales
      const loadInitialNotifications = async () => {
        try {
          if (dataService.getNotifications) {
            const userNotifications = await dataService.getNotifications(currentUser.id);
            setNotifications(userNotifications);
          } else {
            console.warn('La función getNotifications no está disponible');
          }
        } catch (error) {
          console.error('Error al cargar notificaciones iniciales:', error);
        }
      };
      
      loadInitialNotifications();
      
      // Configurar polling como último recurso
      const notificationInterval = setInterval(async () => {
        try {
          const dataService = dataServiceRouter.getService();
          if (dataService.getNotifications) {
            const userNotifications = await dataService.getNotifications(currentUser.id);
            setNotifications(userNotifications);
          } else {
            console.warn('La función notificationInterval no está disponible');
          }
        } catch (error) {
          console.error('Error al actualizar notificaciones:', error);
        }
      }, 5000); // Cada 5 segundos
      
      notificationUnsubscribe = () => clearInterval(notificationInterval);
    }
    
    const unsubscribe = dataService.subscribeToUserData(currentUser.id, (data) => {
        setHomes(data.homes);
        setTasks(data.tasks);
        setInvitations(data.invitations);
        setUsers(data.users);
        setRewards(data.rewards);
        setRewardClaims(data.rewardClaims);
        void taskReminderService.syncTaskReminders(data.tasks).catch((error) => {
          console.warn('[useData] Error al sincronizar recordatorios locales:', error);
        });
        
        // Modificar esta parte para evitar el ciclo infinito
        const selectedHomeId = currentHomeIdRef.current;
        if (selectedHomeId === null && data.homes.length > 0) {
            // Usar una referencia estable para evitar actualizaciones innecesarias
            const firstHomeId = data.homes[0].id;
            if (firstHomeId !== selectedHomeId) {
                currentHomeIdRef.current = firstHomeId;
                setCurrentHomeId(firstHomeId);
            }
        } else if (selectedHomeId && !data.homes.some(h => h.id === selectedHomeId)) {
            const newHomeId = data.homes[0]?.id || null;
            if (newHomeId !== selectedHomeId) {
                currentHomeIdRef.current = newHomeId;
                setCurrentHomeId(newHomeId);
            }
        }
    });

    return () => {
      unsubscribe();
      if (notificationUnsubscribe) {
        notificationUnsubscribe();
      }
    };
    // Eliminar currentHomeId de las dependencias para evitar el ciclo
    }, [currentUser]);
  
  // --- Computed State ---
  const userHomes = useMemo(() => homes, [homes]);
  const currentHome = useMemo(() => {
      const home = homes.find(h => h.id === currentHomeId);
      if(home) {
        // Filtrar tareas activas (pendientes o en proceso)
        const activeTasks = tasks.filter(t => 
          t.homeId === home.id && 
          (t.status === TaskStatus.PENDING || t.status === TaskStatus.IN_PROGRESS)
        );
        
        // Para usuarios gratuitos, no contar las tareas periódicas en el límite
        const plan = currentUser?.plan || 'free';
        const isPremium = plan === 'premium';
        
        let activeTaskCount = activeTasks.length;
        if (!isPremium) {
          // Excluir tareas periódicas del conteo para usuarios gratuitos
          const nonPeriodicActiveTasks = activeTasks.filter(t => t.periodicity === Periodicity.NONE);
          activeTaskCount = nonPeriodicActiveTasks.length;
        }
        
        return {...home, activeTaskCount };
      }
      return undefined;
  }, [currentHomeId, homes, tasks, currentUser]);
  const membersOfCurrentHome = useMemo(() => {
    if (!currentHome) return [];
    return users.filter(u => currentHome.memberIds.includes(u.id));
  }, [currentHome, users]);

  const tasksForCurrentHome = useMemo(() => {
      if (!currentHomeId) return [];
      return tasks.filter(t => t.homeId === currentHomeId)
  }, [tasks, currentHomeId]);

  const pendingInvitations = useMemo(() => invitations.filter(inv => inv.status === 'pending'), [invitations]);
  
  const unreadNotifications = useMemo(() => notifications.filter(n => !n.read), [notifications]);
  
  // --- Methods ---
  const register = (name: string, email: string, password: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.register(name, email, password);
  };
  
  const login = (email: string, password: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.login(email, password);
  };
  
  const resetPassword = (email: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.resetPassword(email);
  };
  
  const googleLogin = async () => {
    try {
      const dataService = dataServiceRouter.getService();
      return await dataService.googleLogin();
    } catch (error: any) {
      console.error('Error en googleLogin:', error);
      return { success: false, message: error.message || 'Error al iniciar sesión con Google' };
    }
  };

  const appleLogin = async () => {
    try {
      const dataService = dataServiceRouter.getService();
      return await dataService.appleLogin();
    } catch (error: any) {
      console.error('Error en appleLogin:', error);
      return { success: false, message: error.message || 'Error al iniciar sesión con Apple' };
    }
  };

  const linkWithGoogle = async () => {
    try {
      const dataService = dataServiceRouter.getService();
      return await dataService.linkWithGoogle();
    } catch (error: any) {
      console.error('Error en linkWithGoogle:', error);
      return { success: false, message: error.message || 'Error al enlazar con Google' };
    }
  };

  const linkWithApple = async () => {
    try {
      const dataService = dataServiceRouter.getService();
      return await dataService.linkWithApple();
    } catch (error: any) {
      console.error('Error en linkWithApple:', error);
      return { success: false, message: error.message || 'Error al enlazar con Apple' };
    }
  };
  
  const logout = () => {
    const dataService = dataServiceRouter.getService();
    return (async () => {
      try {
        // Cerrar siempre sesión Firebase/Google si existe, incluso en modo local.
        if (auth.currentUser) {
          await auth.signOut();
        }
      } catch (error) {
        console.warn('[useData] No se pudo cerrar sesión Firebase completamente:', error);
      }
      await dataService.logout();
    })();
  };
  
  const uploadAvatar = (file: File) => {
      if (!currentUser) throw new Error("No user logged in");
      const dataService = dataServiceRouter.getService();
      return dataService.uploadAvatar(currentUser.id, file);
  }
  
  const updateCurrentUser = (updates: Partial<User> & { password?: string }) => {
    const dataService = dataServiceRouter.getService();
    return dataService.updateCurrentUser(updates);
  }
  
  const addTask = (taskData: NewTaskPayload) => {
    const dataService = dataServiceRouter.getService();
    return dataService.addTask(taskData);
  };
  
  const updateTask = (taskId: string, updates: Partial<Omit<Task, 'id'>>) => {
    const dataService = dataServiceRouter.getService();
    return dataService.updateTask(taskId, updates);
  };
  
  const deleteTask = (taskId: string, deleteAllFuture: boolean = false, selectedDate?: Date) => {
    const dataService = dataServiceRouter.getService();
    return dataService.deleteTask(taskId, deleteAllFuture, selectedDate);
  };
  
  const completeTask = (taskId: string, userId: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.completeTask(taskId, userId);
  };
  
  const createHome = async (name: string) => {
      if(!currentUser) return;
      const dataService = dataServiceRouter.getService();
      await dataService.createHome(name, currentUser);
  }
  
  const updateHome = (homeId: string, updates: Partial<Home>, onComplete?: () => void) => {
    const dataService = dataServiceRouter.getService();
    const result = dataService.updateHome(homeId, updates);
    if (onComplete) {
      onComplete();
    }
    return result;
  }
  
  const sendHomeInvitation = async (email: string, homeId: string) => {
      if (!currentUser || !currentHome) return { success: false, message: "Error interno" };
      const dataService = dataServiceRouter.getService();
      return dataService.sendHomeInvitation(email, currentHome, currentUser);
  }

  const respondToInvitation = async (invitationId: string, accept: boolean) => {
      if (!currentUser) return;
      const dataService = dataServiceRouter.getService();
      await dataService.respondToInvitation(invitationId, accept, currentUser);
  }

  const createHomeInviteLink = async (homeId: string) => {
    const dataService = dataServiceRouter.getService();
    if (!dataService.createHomeInviteLink) {
      return { success: false, message: 'La invitación por enlace no está disponible en este modo.' };
    }
    return dataService.createHomeInviteLink(homeId);
  };

  const joinHomeByInviteToken = async (token: string, options?: JoinHomeByInviteOptions) => {
    return dataServiceRouter.joinHomeByInviteToken(token, options);
  };

  const getJoinHomeInviteOptions = async (token: string) => {
    return dataServiceRouter.getJoinHomeInviteOptions(token);
  };

  const createAnonymousMember = async (name: string, homeId: string) => {
    const dataService = dataServiceRouter.getService();
    if (!dataService.createAnonymousMember) {
      return { success: false, message: 'No disponible en este modo.' };
    }
    return dataService.createAnonymousMember(name, homeId);
  };

  const getStats = useCallback((userId: string, period: 'weekly' | 'monthly' | 'annually'): Stats => {
      const dataService = dataServiceRouter.getService();
      return dataService.getStats(tasks, currentHomeId, userId, period);
  }, [tasks, currentHomeId]);
  
  const togglePremium = async () => {
    const dataService = dataServiceRouter.getService();
    if (dataService.togglePremium && currentUser) {
        await dataService.togglePremium(currentUser.id);
    }
  }

  const leaveHome = (homeId: string, userId: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.leaveHome(homeId, userId);
  };

  const removeUserFromHome = (homeId: string, userId: string, onComplete?: () => void) => {
    const dataService = dataServiceRouter.getService();
    if (dataService.removeUserFromHome) {
      const result = dataService.removeUserFromHome(homeId, userId);
      if (onComplete) {
        onComplete();
      }
      return result;
    }
    return Promise.resolve();
  };

  // La función sendDeleteAccountVerification ya no es necesaria

  const deleteAccount = async (password?: string) => {
    if (!currentUser) return { success: false, message: "No hay usuario conectado" };
    const dataService = dataServiceRouter.getService();
    return dataService.deleteAccount(password);
  };

  // Métodos para notificaciones
  const markNotificationAsRead = async (notificationId: string) => {
    try {
      const dataService = dataServiceRouter.getService();
      if (dataService.markNotificationAsRead) {
        await dataService.markNotificationAsRead(notificationId);
      } else {
        await notificationService.markAsRead(notificationId);
      }
      setNotifications(prev => prev.map(n => 
        n.id === notificationId ? { ...n, read: true } : n
      ));
    } catch (error) {
      console.error('Error al marcar notificación como leída:', error);
    }
  };

  const resendVerificationEmail = () => {
    const dataService = dataServiceRouter.getService();
    return dataService.resendVerificationEmail();
  };

  const createReward = (rewardData: NewRewardPayload, creatorId: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.createReward?.(rewardData, creatorId);
  };
  
  const updateReward = (rewardId: string, updates: Partial<Reward>) => {
    const dataService = dataServiceRouter.getService();
    return dataService.updateReward?.(rewardId, updates);
  };
  
  const deleteReward = (rewardId: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.deleteReward?.(rewardId);
  };
  
  const claimReward = (rewardId: string, userId: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.claimReward?.(rewardId, userId) || Promise.resolve({ success: false, message: 'No implementado' });
  };
  
  const processRewardClaim = (claimId: string, status: RewardStatus, processedBy: string, notes?: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.processRewardClaim?.(claimId, status, processedBy, notes);
  };
  
  const getUserPointsInHome = (userId: string, homeId: string) => {
    const dataService = dataServiceRouter.getService();
    return dataService.getUserPointsInHome?.(userId, homeId) || Promise.resolve(0);
  };


  return {
    authStatus, currentUser, currentHome, userHomes, tasks, tasksForCurrentHome, users, membersOfCurrentHome, pendingInvitations,
    isLocalMode, // NUEVO: indicador de modo local vs firebase
    login, register, resetPassword, googleLogin, appleLogin, linkWithGoogle, linkWithApple, logout, updateCurrentUser, uploadAvatar,
    addTask, updateTask, deleteTask, completeTask, getStats,
    updateTaskStatus: (() => {
      const dataService = dataServiceRouter.getService();
      return dataService.updateTaskStatus?.bind(dataService);
    })(),
    updatePeriodicTaskDayAssignment: (() => {
      const dataService = dataServiceRouter.getService();
      return dataService.updatePeriodicTaskDayAssignment?.bind(dataService);
    })(),
    getPeriodicTaskDayInfo: (() => {
      const dataService = dataServiceRouter.getService();
      return dataService.getPeriodicTaskDayInfo?.bind(dataService);
    })(),
    createHome, updateHome, sendHomeInvitation, respondToInvitation, createHomeInviteLink, joinHomeByInviteToken, getJoinHomeInviteOptions, createAnonymousMember,
    setCurrentHomeId,
    // Notificaciones
    notifications, unreadNotifications, markNotificationAsRead,
    // Dev only
    togglePremium: togglePremium,
    leaveHome,
    removeUserFromHome,
    deleteAccount,
    resendVerificationEmail,
    rewards,
    rewardClaims,
    createReward,
    updateReward,
    deleteReward,
    claimReward,
    processRewardClaim,
    getUserPointsInHome,
    // Nuevos métodos de suscripción
    syncHomeToCloud: async (homeId: string) => {
      const dataService = dataServiceRouter.getService();
      return dataService.syncHomeToCloud?.(homeId) || Promise.resolve({ success: false, message: 'No disponible' });
    },
    upgradeHomeToPremium: async (homeId: string) => {
      const dataService = dataServiceRouter.getService();
      return dataService.upgradeHomeToPremium?.(homeId) || Promise.resolve({ success: false, message: 'No disponible' });
    },
    getSubscriptionStatus: async () => {
      const dataService = dataServiceRouter.getService();
      return dataService.getSubscriptionStatus?.() || Promise.resolve('none');
    },
    activatePremiumCloudMode: async () => {
      return dataServiceRouter.activatePremiumCloudMode();
    }
  };
};


