import React from 'react';
import Modal from './Modal';
import { notificationService } from '../services/notificationService';
import { useAuthState } from 'react-firebase-hooks/auth';
import { auth } from '../services/firebase';
import { useAppConfig } from '../hooks/useAppConfig';
import { useI18n } from '../i18n/I18nProvider';
import { isPremiumPurchaseEnabledForPlatform } from '../services/appConfigService';

interface UpgradeModalProps {
  isOpen: boolean;
  onClose: () => void;
  onUpgrade: () => void;
  reason: string;
}

const UpgradeModal: React.FC<UpgradeModalProps> = ({ isOpen, onClose, onUpgrade, reason }) => {
  const [user] = useAuthState(auth);
  const { appConfig } = useAppConfig();
  const { t } = useI18n();
  const runtimePlatform = (() => {
    const cap = (typeof window !== 'undefined') ? (window as any).Capacitor : null;
    if (cap?.isNativePlatform?.()) {
      const p = cap.getPlatform?.();
      if (p === 'ios' || p === 'android') return p as 'ios' | 'android';
    }
    return 'web' as const;
  })();
  const purchaseEnabledOnPlatform = isPremiumPurchaseEnabledForPlatform(appConfig, runtimePlatform);
  
  const handleUpgradeClick = async () => {
    if (!purchaseEnabledOnPlatform) return;
    if (user) {
      await notificationService.recordPremiumFeatureAttempt(
        user.uid,
        'upgrade_modal_click',
        {
          reason,
          source: 'upgrade_modal'
        }
      );
    }
    onUpgrade();
  };
  
  const handleCloseClick = async () => {
    if (user) {
      await notificationService.recordPremiumFeatureAttempt(
        user.uid,
        'upgrade_modal_dismiss',
        {
          reason,
          source: 'upgrade_modal'
        }
      );
    }
    onClose();
  };
  
  if (!isOpen) return null;

  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <div className="p-6 text-center">
        <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-gradient-to-r from-secondary-200 to-primary-200 mb-4">
          <span className="text-4xl">✨</span>
        </div>
        <h3 className="text-2xl font-bold text-slate-800 dark:text-slate-100">
          {t('upgrade.title')}
        </h3>
        <div className="mt-2 px-4 text-sm text-slate-600 dark:text-slate-300">
          <p>{reason}</p>
        </div>
        <div className="mt-6 flex flex-col sm:flex-row gap-3 justify-center">
          <button
            onClick={handleCloseClick}
            type="button"
            className="w-full sm:w-auto inline-flex justify-center rounded-md border border-transparent px-4 py-2 bg-slate-200 dark:bg-slate-700 text-base font-medium text-slate-700 dark:text-slate-200 hover:bg-slate-300 dark:hover:bg-slate-600"
          >
            {t('upgrade.understood')}
          </button>
          {/* Para reactivar el botón, quitar la propiedad 'disabled' y el estilo de opacidad y cursor-not-allowed */}
          <button
            onClick={handleUpgradeClick}
            type="button"
            disabled={!purchaseEnabledOnPlatform}
            className="w-full sm:w-auto inline-flex justify-center rounded-md border border-transparent shadow-sm px-4 py-2 bg-primary-600 text-base font-medium text-white hover:bg-primary-700 disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {purchaseEnabledOnPlatform ? t('settings.invite.buyPremium') : t('settings.invite.premiumDisabled')}
          </button>
        </div>
      </div>
    </Modal>
  );
};

export default UpgradeModal;
