import React, { useState, useEffect } from 'react';
import Modal from './Modal';

interface DeleteAccountModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirmDelete: (password: string) => Promise<void>;
}

const DeleteAccountModal: React.FC<DeleteAccountModalProps> = ({ isOpen, onClose, onConfirmDelete }) => {
  const [verificationCode, setVerificationCode] = useState('');
  const [generatedCode, setGeneratedCode] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  
  // Generar un código de verificación de 4 números aleatorios cuando se abre el modal
  useEffect(() => {
    if (isOpen) {
      const randomCode = Math.floor(1000 + Math.random() * 9000).toString();
      setGeneratedCode(randomCode);
      setVerificationCode('');
      setPassword('');
      setError('');
    }
  }, [isOpen]);

  const handleConfirmDelete = async () => {
    setError('');
    
    if (verificationCode !== generatedCode) {
      setError('El código de verificación no es correcto. Por favor, introduce el código mostrado.');
      return;
    }

    if (!password) {
      setError('Por favor, introduce tu contraseña para confirmar.');
      return;
    }
    
    setLoading(true);
    
    try {
      await onConfirmDelete(password);
      // No necesitamos cerrar el modal aquí ya que la cuenta se eliminará
      // y el usuario será redirigido a la página de inicio de sesión
    } catch (err: any) {
      setError(err.message || 'Error al eliminar la cuenta. Inténtalo de nuevo.');
      setLoading(false);
    }
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose}>
      <div className="p-6 space-y-6">
        <h3 className="text-2xl font-bold text-red-600 dark:text-red-500">Eliminar cuenta</h3>
        
        <div className="space-y-4">
          <div className="bg-red-100 dark:bg-red-900/50 border-l-4 border-red-500 p-4 rounded">
            <p className="text-red-700 dark:text-red-300 font-medium">¡Advertencia! Esta acción es irreversible.</p>
            <p className="text-red-600 dark:text-red-200 mt-2">
              Al eliminar tu cuenta:
            </p>
            <ul className="list-disc list-inside text-red-600 dark:text-red-200 mt-1 space-y-1">
              <li>Se eliminarán todos tus datos personales</li>
              <li>Perderás acceso a todas tus casas</li>
              <li>Las tareas que hayas creado permanecerán en las casas, pero sin tu nombre</li>
              <li>Si eres el único miembro de una casa, esta será eliminada junto con todas sus tareas</li>
            </ul>
          </div>
          
          <div>
            <div className="p-4 bg-gray-100 dark:bg-slate-800 rounded-md mb-4">
              <p className="mb-2 font-medium">Código de verificación:</p>
              <div className="text-2xl font-bold text-center tracking-wider bg-white dark:bg-slate-700 p-3 rounded border dark:border-slate-600">
                {generatedCode}
              </div>
            </div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Introduce el código de verificación mostrado arriba:
            </label>
            <input 
              type="text" 
              value={verificationCode} 
              onChange={(e) => setVerificationCode(e.target.value)}
              className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded"
              placeholder="Código de 4 números"
              maxLength={4}
            />
          </div>
          
          <div className="mt-4">
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Introduce tu contraseña para confirmar
            </label>
            <input 
              type="password" 
              value={password} 
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-2 border border-gray-300 dark:border-slate-600 dark:bg-slate-700 rounded"
              placeholder="Contraseña"
            />
          </div>
          
          {error && (
            <p className="text-red-600 dark:text-red-400 text-sm">{error}</p>
          )}
        </div>
        
        <div className="flex justify-end space-x-3">
          <button 
            onClick={onClose}
            className="py-2 px-4 bg-slate-200 hover:bg-slate-300 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 rounded-md font-bold"
          >
            Cancelar
          </button>
          <button 
            onClick={handleConfirmDelete}
            disabled={verificationCode.length !== 4 || !password || loading}
            className="py-2 px-4 bg-red-600 hover:bg-red-700 text-white rounded-md font-bold disabled:bg-red-300 disabled:dark:bg-red-800/50"
          >
            {loading ? 'Eliminando...' : 'Eliminar mi cuenta'}
          </button>
        </div>
      </div>
    </Modal>
  );
};

export default DeleteAccountModal;