import { httpsCallable } from 'firebase/functions';
import { functions } from './firebase';
import { AppConfig } from '../types';
import { auth } from './firebase';
import { db } from './firebase';
import { doc, getDoc, setDoc } from 'firebase/firestore';

export const DEFAULT_APP_CONFIG: AppConfig = {
  limits: {
    freeMaxHomes: 1,
    premiumMaxHomes: 2,
    freeMaxMembersPerHome: 2,
    freeMaxActiveTasks: 20,
    freeMaxPeriodicTaskTemplates: 3,
    freeMaxActiveRewards: 1,
    premiumMaxActiveRewards: 25,
  },
  minimumVersions: {
    ios: '0.0.0',
    android: '0.0.0',
  },
  review: {
    iosUrl: '',
    androidUrl: '',
    promptEnabled: false,
    promptAfterMinutes: 15,
    promptCooldownDays: 14,
  },
  updateUrls: {
    ios: '',
    android: '',
  },
  premium: {
    monthlyPriceLabel: '2,50EUR',
    yearlyPriceLabel: '25EUR',
    yearlyMonthlyEquivalentLabel: '2,08EUR',
    purchaseEnabled: true,
    purchaseEnabledByPlatform: {
      web: true,
      ios: true,
      android: true,
    },
    premiumBypassEmails: [],
  },
  updatedAt: 0,
};

const toNumber = (value: any, fallback: number): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};

const toString = (value: any, fallback: string): string => {
  return typeof value === 'string' ? value : fallback;
};

const toBoolean = (value: any, fallback: boolean): boolean => {
  return typeof value === 'boolean' ? value : fallback;
};

const toEmailList = (value: any): string[] => {
  if (!Array.isArray(value)) return [];
  return Array.from(new Set(
    value
      .map((item) => String(item || '').trim().toLowerCase())
      .filter(Boolean)
  ));
};

export const sanitizeAppConfig = (input?: Partial<AppConfig> | null): AppConfig => {
  const candidate = input || {};
  return {
    limits: {
      freeMaxHomes: Math.max(1, Math.floor(toNumber(candidate.limits?.freeMaxHomes, DEFAULT_APP_CONFIG.limits.freeMaxHomes))),
      premiumMaxHomes: Math.max(1, Math.floor(toNumber(candidate.limits?.premiumMaxHomes, DEFAULT_APP_CONFIG.limits.premiumMaxHomes))),
      freeMaxMembersPerHome: Math.max(1, Math.floor(toNumber(candidate.limits?.freeMaxMembersPerHome, DEFAULT_APP_CONFIG.limits.freeMaxMembersPerHome))),
      freeMaxActiveTasks: Math.max(1, Math.floor(toNumber(candidate.limits?.freeMaxActiveTasks, DEFAULT_APP_CONFIG.limits.freeMaxActiveTasks))),
      freeMaxPeriodicTaskTemplates: Math.max(1, Math.floor(toNumber(candidate.limits?.freeMaxPeriodicTaskTemplates, DEFAULT_APP_CONFIG.limits.freeMaxPeriodicTaskTemplates))),
      freeMaxActiveRewards: Math.max(1, Math.floor(toNumber(candidate.limits?.freeMaxActiveRewards, DEFAULT_APP_CONFIG.limits.freeMaxActiveRewards))),
      premiumMaxActiveRewards: Math.max(1, Math.floor(toNumber(candidate.limits?.premiumMaxActiveRewards, DEFAULT_APP_CONFIG.limits.premiumMaxActiveRewards))),
    },
    minimumVersions: {
      ios: toString(candidate.minimumVersions?.ios, DEFAULT_APP_CONFIG.minimumVersions.ios).trim(),
      android: toString(candidate.minimumVersions?.android, DEFAULT_APP_CONFIG.minimumVersions.android).trim(),
    },
    review: {
      iosUrl: toString(candidate.review?.iosUrl, DEFAULT_APP_CONFIG.review.iosUrl).trim(),
      androidUrl: toString(candidate.review?.androidUrl, DEFAULT_APP_CONFIG.review.androidUrl).trim(),
      promptEnabled: toBoolean(candidate.review?.promptEnabled, DEFAULT_APP_CONFIG.review.promptEnabled),
      promptAfterMinutes: Math.max(1, Math.floor(toNumber(candidate.review?.promptAfterMinutes, DEFAULT_APP_CONFIG.review.promptAfterMinutes))),
      promptCooldownDays: Math.max(0, Math.floor(toNumber(candidate.review?.promptCooldownDays, DEFAULT_APP_CONFIG.review.promptCooldownDays))),
    },
    updateUrls: {
      ios: toString(candidate.updateUrls?.ios, DEFAULT_APP_CONFIG.updateUrls.ios).trim(),
      android: toString(candidate.updateUrls?.android, DEFAULT_APP_CONFIG.updateUrls.android).trim(),
    },
    premium: {
      monthlyPriceLabel: toString(candidate.premium?.monthlyPriceLabel, DEFAULT_APP_CONFIG.premium.monthlyPriceLabel).trim(),
      yearlyPriceLabel: toString(candidate.premium?.yearlyPriceLabel, DEFAULT_APP_CONFIG.premium.yearlyPriceLabel).trim(),
      yearlyMonthlyEquivalentLabel: toString(candidate.premium?.yearlyMonthlyEquivalentLabel, DEFAULT_APP_CONFIG.premium.yearlyMonthlyEquivalentLabel).trim(),
      purchaseEnabled: toBoolean(candidate.premium?.purchaseEnabled, DEFAULT_APP_CONFIG.premium.purchaseEnabled),
      purchaseEnabledByPlatform: {
        web: toBoolean(candidate.premium?.purchaseEnabledByPlatform?.web, DEFAULT_APP_CONFIG.premium.purchaseEnabledByPlatform?.web ?? true),
        ios: toBoolean(candidate.premium?.purchaseEnabledByPlatform?.ios, DEFAULT_APP_CONFIG.premium.purchaseEnabledByPlatform?.ios ?? true),
        android: toBoolean(candidate.premium?.purchaseEnabledByPlatform?.android, DEFAULT_APP_CONFIG.premium.purchaseEnabledByPlatform?.android ?? true),
      },
      premiumBypassEmails: toEmailList(candidate.premium?.premiumBypassEmails),
    },
    updatedAt: Math.floor(toNumber(candidate.updatedAt, Date.now())),
  };
};

let cachedConfig: AppConfig | null = null;
let inflightPromise: Promise<AppConfig> | null = null;
const APP_CONFIG_CACHE_KEY = 'housezen_app_config_cache_v1';
const APP_CONFIG_CACHE_AT_KEY = 'housezen_app_config_cache_at_v1';
const ONE_DAY_MS = 24 * 60 * 60 * 1000;
const isLocalDev =
  typeof window !== 'undefined' &&
  (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');

const readStoredConfig = (): AppConfig | null => {
  try {
    const rawConfig = localStorage.getItem(APP_CONFIG_CACHE_KEY);
    const rawCachedAt = localStorage.getItem(APP_CONFIG_CACHE_AT_KEY);
    if (!rawConfig || !rawCachedAt) return null;
    const cachedAt = Number(rawCachedAt);
    if (!Number.isFinite(cachedAt)) return null;
    if (Date.now() - cachedAt > ONE_DAY_MS) return null;
    const parsed = JSON.parse(rawConfig);
    return sanitizeAppConfig(parsed as Partial<AppConfig>);
  } catch {
    return null;
  }
};

const storeConfig = (config: AppConfig) => {
  try {
    localStorage.setItem(APP_CONFIG_CACHE_KEY, JSON.stringify(config));
    localStorage.setItem(APP_CONFIG_CACHE_AT_KEY, String(Date.now()));
  } catch {
    // ignore local storage quota/runtime errors
  }
};

export const appConfigService = {
  async getConfig(forceRefresh = false): Promise<AppConfig> {
    if (!forceRefresh && cachedConfig) {
      return cachedConfig;
    }

    if (!forceRefresh) {
      const stored = readStoredConfig();
      if (stored) {
        cachedConfig = stored;
        return stored;
      }
    }

    if (!forceRefresh && inflightPromise) {
      return inflightPromise;
    }

    inflightPromise = (async () => {
      if (isLocalDev) {
        try {
          const configRef = doc(db, 'appConfig', 'global');
          const snapshot = await getDoc(configRef);
          if (snapshot.exists()) {
            const normalized = sanitizeAppConfig(snapshot.data() as Partial<AppConfig>);
            cachedConfig = normalized;
            storeConfig(normalized);
            return normalized;
          }
        } catch (firestoreError) {
          console.warn('[appConfigService] getConfig Firestore local-dev falló.', firestoreError);
        }
      }

      try {
        const callable = httpsCallable(functions, 'getAppConfig');
        const result = await callable({});
        const payload = (result.data as any)?.config || result.data;
        const normalized = sanitizeAppConfig(payload as Partial<AppConfig>);
        cachedConfig = normalized;
        storeConfig(normalized);
        return normalized;
      } catch (error) {
        console.warn('[appConfigService] Callable getAppConfig falló, intentando fallback Firestore.', error);
        try {
          const configRef = doc(db, 'appConfig', 'global');
          const snapshot = await getDoc(configRef);
          if (snapshot.exists()) {
            const normalized = sanitizeAppConfig(snapshot.data() as Partial<AppConfig>);
            cachedConfig = normalized;
            storeConfig(normalized);
            return normalized;
          }
        } catch (firestoreError) {
          console.warn('[appConfigService] Fallback Firestore también falló.', firestoreError);
        }

        const fallback = sanitizeAppConfig(cachedConfig || readStoredConfig() || DEFAULT_APP_CONFIG);
        cachedConfig = fallback;
        storeConfig(fallback);
        return fallback;
      } finally {
        inflightPromise = null;
      }
    })();

    return inflightPromise;
  },

  async saveConfig(config: AppConfig, adminPassword?: string): Promise<{ success: boolean; message: string; config: AppConfig }> {
    const sanitized = sanitizeAppConfig(config);
    if (isLocalDev) {
      if (!auth.currentUser) {
        return {
          success: false,
          message: 'Debes iniciar sesión con Google para guardar la configuración en modo desarrollo.',
          config: sanitizeAppConfig(cachedConfig || sanitized),
        };
      }
      try {
        const configRef = doc(db, 'appConfig', 'global');
        const payloadToSave = {
          ...sanitized,
          updatedAt: Date.now(),
        };
        await setDoc(configRef, payloadToSave, { merge: true });
        const savedConfig = sanitizeAppConfig(payloadToSave);
        cachedConfig = savedConfig;
        storeConfig(savedConfig);
        return {
          success: true,
          message: 'Configuración guardada.',
          config: savedConfig,
        };
      } catch (firestoreError: any) {
        return {
          success: false,
          message: firestoreError?.message || 'No se pudo guardar la configuración.',
          config: sanitizeAppConfig(cachedConfig || sanitized),
        };
      }
    }

    try {
      const callable = httpsCallable(functions, 'setAppConfig');
      const response = await callable({
        config: sanitized,
        adminPassword: String(adminPassword || ''),
        requesterUid: auth.currentUser?.uid || null,
      });
      const payload = (response.data as any)?.config || response.data;
      const savedConfig = sanitizeAppConfig(payload as Partial<AppConfig>);
      cachedConfig = savedConfig;
      storeConfig(savedConfig);
      return {
        success: true,
        message: 'Configuración guardada.',
        config: savedConfig,
      };
    } catch (error) {
      console.warn('[appConfigService] Callable setAppConfig falló, intentando fallback Firestore.', error);
      try {
        const configRef = doc(db, 'appConfig', 'global');
        const payloadToSave = {
          ...sanitized,
          updatedAt: Date.now(),
        };
        await setDoc(configRef, payloadToSave, { merge: true });
        const savedConfig = sanitizeAppConfig(payloadToSave);
        cachedConfig = savedConfig;
        storeConfig(savedConfig);
        return {
          success: true,
          message: 'Configuración guardada (fallback Firestore).',
          config: savedConfig,
        };
      } catch (firestoreError: any) {
        return {
          success: false,
          message: firestoreError?.message || 'No se pudo guardar la configuración.',
          config: sanitizeAppConfig(cachedConfig || sanitized),
        };
      }
    }
  },

  getCachedConfig(): AppConfig | null {
    return cachedConfig;
  },
};

export const isPremiumPurchaseEnabledForPlatform = (
  appConfig: AppConfig,
  platform: 'web' | 'ios' | 'android'
): boolean => {
  if (!appConfig.premium.purchaseEnabled) return false;
  const byPlatform = appConfig.premium.purchaseEnabledByPlatform;
  if (!byPlatform) return true;
  return Boolean(byPlatform[platform]);
};
