import React, { useState, useEffect } from 'react';
import { usePlatform } from '../hooks/usePlatform';
import { useData } from '../hooks/useData';

interface BeforeInstallPromptEvent extends Event {
  readonly platforms: string[];
  readonly userChoice: Promise<{ outcome: 'accepted' | 'dismissed', platform: string }>;
  prompt(): Promise<void>;
}

interface InstallAppProps {
  className?: string;
}

const InstallApp: React.FC<InstallAppProps> = ({ className = '' }) => {
  const { platform } = usePlatform();
  const { authStatus } = useData();
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [showIOSInstructions, setShowIOSInstructions] = useState(false);
  const [isInstalled, setIsInstalled] = useState(false);
  const [installAttempted, setInstallAttempted] = useState(false);

  // Comprobar si la aplicación ya está instalada
  useEffect(() => {
    // Detectar si la app ya está instalada como PWA
    const isInStandaloneMode = () => 
      window.matchMedia('(display-mode: standalone)').matches ||
      (window.navigator as any).standalone ||
      document.referrer.includes('android-app://');

    if (isInStandaloneMode()) {
      setIsInstalled(true);
    }

    // También escuchar cambios en el modo de visualización
    const mediaQuery = window.matchMedia('(display-mode: standalone)');
    const handleChange = (e: MediaQueryListEvent) => {
      setIsInstalled(e.matches);
    };
    
    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  useEffect(() => {
    const handleBeforeInstallPrompt = (e: Event) => {
      // Prevent Chrome 67 and earlier from automatically showing the prompt
      e.preventDefault();
      // Stash the event so it can be triggered later
      setDeferredPrompt(e as BeforeInstallPromptEvent);
      console.log('Evento beforeinstallprompt capturado', e);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    // También detectar cuando la app se ha instalado
    const handleAppInstalled = () => {
      setIsInstalled(true);
      setDeferredPrompt(null);
      console.log('App instalada correctamente');
    };

    window.addEventListener('appinstalled', handleAppInstalled);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, []);

  // Intentar mostrar el prompt automáticamente después de cargar
  useEffect(() => {
    // Solo intentar una vez y solo en Android
    if (platform === 'android' && deferredPrompt && !installAttempted && !isInstalled) {
      const timer = setTimeout(() => {
        handleInstallClick();
        setInstallAttempted(true);
      }, 3000); // Esperar 3 segundos antes de mostrar
      
      return () => clearTimeout(timer);
    }
  }, [deferredPrompt, platform, installAttempted, isInstalled]);

  const handleInstallClick = async () => {
    if (platform === 'android') {
      if (deferredPrompt) {
        try {
          // Show the install prompt
          await deferredPrompt.prompt();
          
          // Wait for the user to respond to the prompt
          const { outcome } = await deferredPrompt.userChoice;
          
          // We no longer need the prompt. Clear it up
          setDeferredPrompt(null);
          
          if (outcome === 'accepted') {
            console.log('Usuario aceptó la instalación');
            setIsInstalled(true);
          } else {
            console.log('Usuario rechazó la instalación');
          }
        } catch (error) {
          console.error('Error al mostrar el prompt de instalación:', error);
        }
      } else {
        // Si no tenemos el evento deferredPrompt, mostramos instrucciones manuales
        alert('Para instalar la aplicación: \n1. Abre el menú de Chrome (tres puntos) \n2. Selecciona "Instalar aplicación" o "Añadir a pantalla de inicio"');
      }
    } else if (platform === 'ios') {
      setShowIOSInstructions(true);
    }
  };

  // Ocultar los botones si el usuario está autenticado o si la app ya está instalada
  if (isInstalled) {
    return null;
  }

  // Renderizar botón según la plataforma
  const renderButton = () => {
    if (platform === 'android') {
      return (
        <button
          onClick={handleInstallClick}
          className="flex items-center justify-center gap-1 bg-green-600 hover:bg-green-700 text-white font-medium py-1 px-3 rounded-lg text-sm transition-transform duration-200 hover:scale-105"
          aria-label="Instalar en Android"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 24 24" fill="currentColor">
            <path d="M17.523 15.3414c-.5511 0-.9993-.4486-.9993-.9997s.4483-.9993.9993-.9993c.5511 0 .9993.4483.9993.9993.0001.5511-.4482.9997-.9993.9997m-11.046 0c-.5511 0-.9993-.4486-.9993-.9997s.4482-.9993.9993-.9993c.5511 0 .9993.4483.9993.9993 0 .5511-.4483.9997-.9993.9997m11.4045-6.02l1.9973-3.4592a.416.416 0 00-.1521-.5676.416.416 0 00-.5676.1521l-2.0223 3.503C15.5902 8.2439 13.8533 7.8508 12 7.8508s-3.5902.3931-5.1367 1.0729L4.841 5.4207a.4161.4161 0 00-.5677-.1521.4157.4157 0 00-.1521.5676l1.9973 3.4592C2.6889 11.1867.3432 14.6589 0 18.761h24c-.3435-4.1021-2.6892-7.5743-6.1185-9.4396"/>
          </svg>
          <span>Instalar</span>
        </button>
      );
    } else if (platform === 'ios') {
      return (
        <button
          onClick={() => setShowIOSInstructions(true)}
          className="flex items-center justify-center gap-1 bg-blue-600 hover:bg-blue-700 text-white font-medium py-1 px-3 rounded-lg text-sm transition-transform duration-200 hover:scale-105"
          aria-label="Instalar en iOS"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 24 24" fill="currentColor">
            <path d="M16.462 8.583c-.307 0-1.085.674-2.081.674-.997 0-1.798-.674-2.106-.674-1.419 0-3.333 2.76-3.333 5.461 0 2.701 2.135 7.046 3.554 7.046.673 0 1.419-.674 2.39-.674.949 0 1.491.674 2.164.674 1.419 0 3.333-3.986 3.333-6.686-.025 0-2.341-.842-2.341-3.554 0-2.39 1.995-3.277 2.045-3.277-.05-.125-1.344-2.736-3.625-2.736zM16.307 3c.05 1.545-1.142 3.089-2.561 3.089-1.394 0-2.786-1.545-2.736-3.089 0-1.545 1.242-3.089 2.736-3.089 1.444 0 2.511 1.545 2.561 3.089z"/>
          </svg>
          <span>Instalar</span>
        </button>
      );
    }
    return null;
  };

  return (
    <div className={`flex items-center gap-2 ${className}`}>
      {/* Renderizar botón según plataforma */}
      {authStatus !== 'logged-in' && renderButton()}

      {/* Modal con instrucciones para iOS */}
      {showIOSInstructions && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white dark:bg-slate-800 rounded-lg p-6 max-w-sm w-full shadow-xl transform translate-y-28">
            <h3 className="text-lg font-bold mb-4 text-slate-900 dark:text-white">
              Instalar en iOS
            </h3>
            <ol className="list-decimal pl-5 mb-4 text-slate-700 dark:text-slate-300 space-y-3">
              <li>
                Toca el icono de compartir en Safari{" "}
                <span className="inline-block">⎙</span>
              </li>
              <li>Desplázate hacia abajo y toca "Añadir a pantalla de inicio"</li>
              <li>Toca "Añadir" en la esquina superior derecha</li>
            </ol>
            <div className="flex justify-end mt-4">
              <button
                onClick={() => setShowIOSInstructions(false)}
                className="bg-primary-600 hover:bg-primary-700 text-white font-medium py-2 px-4 rounded-lg"
              >
                Entendido
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default InstallApp;